import { useEffect, useId, useState } from 'react';

export interface User {
  id: string | number;
  name: string;
  email: string;
}

function isUser(value: unknown): value is User {
  if (typeof value !== 'object' || value === null) return false;
  return (
    'id' in value &&
    (typeof value.id === 'string' || typeof value.id === 'number') &&
    'name' in value && typeof value.name === 'string' &&
    'email' in value && typeof value.email === 'string'
  );
}

export function UserSearch() {
  const inputId = useId();
  const sortId = useId();
  const [query, setQuery] = useState('');
  const [sortBy, setSortBy] = useState<'name' | 'email'>('name');
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const term = query.trim();

  useEffect(() => {
    const controller = new AbortController();
    let active = true;
    setUsers([]);
    setError(null);
    setLoading(Boolean(term));

    if (!term) return;

    const timer = setTimeout(async () => {
      try {
        const response = await fetch(`/api/users?q=${encodeURIComponent(term)}`, {
          signal: controller.signal,
        });
        if (!response.ok) {
          throw new Error(`Unable to load users (HTTP ${response.status}).`);
        }
        const data: unknown = await response.json();
        if (!Array.isArray(data) || !data.every(isUser)) {
          throw new Error('The server returned an invalid user list.');
        }
        if (active) setUsers(data);
      } catch (cause: unknown) {
        if (active) {
          setError(cause instanceof Error ? cause.message : 'Unable to load users.');
        }
      } finally {
        if (active) setLoading(false);
      }
    }, 300);

    return () => {
      active = false;
      clearTimeout(timer);
      controller.abort();
    };
  }, [term]);

  const sortedUsers = [...users].sort((a, b) => a[sortBy].localeCompare(b[sortBy]));

  return (
    <section aria-label="User search">
      <label htmlFor={inputId}>Search users</label>
      <input
        id={inputId}
        type="search"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        placeholder="Search by name or email"
      />

      <label htmlFor={sortId}>Sort results by</label>
      <select
        id={sortId}
        value={sortBy}
        onChange={(event) => setSortBy(event.target.value === 'email' ? 'email' : 'name')}
      >
        <option value="name">Name</option>
        <option value="email">Email</option>
      </select>

      <p role="status">
        {loading
          ? 'Loading users…'
          : error
            ? 'Search failed.'
            : !term
              ? 'Type to search for users.'
              : `${users.length} ${users.length === 1 ? 'result' : 'results'}`}
      </p>
      {error && <p role="alert">{error}</p>}

      <ul aria-label="Matching users" aria-busy={loading}>
        {sortedUsers.map((user) => (
          <li key={user.id}>
            <span>ID: {user.id}</span>{' — '}
            <span>{user.name}</span>{' — '}
            <span>{user.email}</span>
          </li>
        ))}
      </ul>
    </section>
  );
}

export default UserSearch;

import { useEffect, useId, useMemo, useState } from "react";

export interface User {
  id: string | number;
  name: string;
  email: string;
}

function isUserList(value: unknown): value is User[] {
  return Array.isArray(value) && value.every((user: unknown) => {
    if (typeof user !== "object" || user === null) return false;
    return "id" in user && (typeof user.id === "string" || typeof user.id === "number")
      && "name" in user && typeof user.name === "string"
      && "email" in user && typeof user.email === "string";
  });
}

export function UserSearch() {
  const searchId = useId();
  const sortId = useId();
  const [query, setQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [sortBy, setSortBy] = useState<"name" | "email">("name");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const term = query.trim();

  useEffect(() => {
    const controller = new AbortController();
    let active = true;
    setUsers([]);
    setError(null);
    setLoading(term.length > 0);

    if (!term) return () => controller.abort();

    const timeout = setTimeout(async () => {
      try {
        const response = await fetch(`/api/users?q=${encodeURIComponent(term)}`, {
          signal: controller.signal,
        });
        if (!response.ok) throw new Error(`User search failed (${response.status}).`);
        const data: unknown = await response.json();
        if (!isUserList(data)) throw new Error("The server returned an invalid user list.");
        if (active) setUsers(data);
      } catch (cause: unknown) {
        if (active) {
          setError(cause instanceof Error ? cause.message : "Unable to search users.");
        }
      } finally {
        if (active) setLoading(false);
      }
    }, 300);

    return () => {
      active = false;
      clearTimeout(timeout);
      controller.abort();
    };
  }, [term]);

  const sortedUsers = useMemo(
    () => [...users].sort((a, b) => a[sortBy].localeCompare(b[sortBy])),
    [users, sortBy],
  );

  return (
    <section aria-label="User search">
      <label htmlFor={searchId}>Search users</label>
      <input
        id={searchId}
        type="search"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        placeholder="Search by name or email"
      />

      <label htmlFor={sortId}>Sort results by</label>
      <select
        id={sortId}
        value={sortBy}
        onChange={(event) => setSortBy(event.target.value === "email" ? "email" : "name")}
      >
        <option value="name">Name</option>
        <option value="email">Email</option>
      </select>

      <p role="status">
        {loading ? "Loading users…" : !term ? "Type to search users."
          : error ? "Search unsuccessful."
          : `${users.length} ${users.length === 1 ? "result" : "results"}`}
      </p>
      {error && <p role="alert">{error}</p>}
      {!loading && !error && term && users.length === 0 && <p>No matching users.</p>}
      {sortedUsers.length > 0 && (
        <ul>
          {sortedUsers.map((user) => (
            <li key={user.id}>
              <span>ID: {user.id}</span>{" — "}
              <span>{user.name}</span>{" — "}
              <span>{user.email}</span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

export default UserSearch;

import { useEffect, useState } from "react";

type Metric = { name: string; value: number; unit: string };
type Snapshot = {
  metrics: Metric[];
  changed: Set<string>;
  updatedAt: number;
};

function isMetrics(data: unknown): data is Metric[] {
  return (
    Array.isArray(data) &&
    data.every(
      (metric: unknown) =>
        typeof metric === "object" &&
        metric !== null &&
        "name" in metric && typeof metric.name === "string" &&
        "value" in metric && typeof metric.value === "number" &&
        Number.isFinite(metric.value) &&
        "unit" in metric && typeof metric.unit === "string",
    )
  );
}

export function MetricsPanel() {
  const [snapshot, setSnapshot] = useState<Snapshot | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [now, setNow] = useState(Date.now);

  useEffect(() => {
    let disposed = false;
    let request: AbortController | null = null;
    let pollingTimer: ReturnType<typeof setInterval> | undefined;
    let clockTimer: ReturnType<typeof setInterval> | undefined;
    let previousValues = new Map<string, number>();

    async function refresh() {
      if (disposed || request) return;
      const controller = new AbortController();
      request = controller;

      try {
        const response = await fetch("/api/metrics", {
          signal: controller.signal,
          cache: "no-store",
        });
        if (!response.ok) throw new Error(`Request failed (${response.status})`);
        const metrics: unknown = await response.json();
        if (!isMetrics(metrics)) throw new Error("Invalid metrics response");
        if (disposed || controller.signal.aborted) return;

        const changed = new Set(
          metrics
            .filter((metric) =>
              previousValues.has(metric.name) &&
              previousValues.get(metric.name) !== metric.value,
            )
            .map((metric) => metric.name),
        );
        previousValues = new Map(metrics.map(({ name, value }) => [name, value]));
        const updatedAt = Date.now();
        setSnapshot({ metrics, changed, updatedAt });
        setNow(updatedAt);
        setError(null);
      } catch (cause) {
        if (!disposed && !controller.signal.aborted) {
          setError(cause instanceof Error ? cause.message : "Unable to load metrics");
        }
      } finally {
        if (request === controller) request = null;
      }
    }

    function stopTimers() {
      clearInterval(pollingTimer);
      clearInterval(clockTimer);
    }

    function startTimers() {
      stopTimers();
      pollingTimer = setInterval(() => void refresh(), 10_000);
      clockTimer = setInterval(() => setNow(Date.now()), 1_000);
    }

    function onVisibilityChange() {
      stopTimers();
      if (document.hidden) {
        request?.abort();
        request = null;
      } else {
        setNow(Date.now());
        void refresh();
        startTimers();
      }
    }

    document.addEventListener("visibilitychange", onVisibilityChange);
    void refresh();
    if (!document.hidden) startTimers();

    return () => {
      disposed = true;
      stopTimers();
      request?.abort();
      document.removeEventListener("visibilitychange", onVisibilityChange);
    };
  }, []);

  const secondsAgo = snapshot
    ? Math.max(0, Math.floor((now - snapshot.updatedAt) / 1_000))
    : null;

  return (
    <section aria-label="Metrics" style={{ padding: "1.5rem", fontFamily: "system-ui" }}>
      <h2>Metrics</h2>
      {secondsAgo !== null && <p>last updated {secondsAgo} seconds ago</p>}
      {error && <p role="alert">Could not refresh metrics: {error}</p>}
      {!snapshot && !error && <p role="status">Loading metrics…</p>}
      {snapshot?.metrics.length === 0 && <p>No metrics available.</p>}
      {snapshot && snapshot.metrics.length > 0 && (
        <dl style={{ display: "grid", gap: "0.75rem", margin: 0 }}>
          {snapshot.metrics.map(({ name, value, unit }) => {
            const changed = snapshot.changed.has(name);
            return (
              <div
                key={name}
                data-changed={changed}
                style={{
                  padding: "1rem",
                  border: `1px solid ${changed ? "#a16207" : "#d1d5db"}`,
                  borderRadius: "0.5rem",
                  backgroundColor: changed ? "#fef3c7" : "#ffffff",
                  color: "#111827",
                }}
              >
                <dt>{name}</dt>
                <dd style={{ margin: "0.25rem 0 0", fontSize: "1.5rem" }}>
                  {value} {unit}
                  {changed && <small style={{ marginLeft: "0.75rem", fontSize: "0.875rem" }}>Changed</small>}
                </dd>
              </div>
            );
          })}
        </dl>
      )}
    </section>
  );
}

export default MetricsPanel;

import { useEffect, useState } from "react";

export interface Metric {
  name: string;
  value: number;
  unit: string;
}

function isMetrics(data: unknown): data is Metric[] {
  return Array.isArray(data) && data.every((metric: unknown) => {
    if (typeof metric !== "object" || metric === null) return false;
    const entry = metric as Record<string, unknown>;
    return typeof entry.name === "string"
      && typeof entry.value === "number" && Number.isFinite(entry.value)
      && typeof entry.unit === "string";
  });
}

export function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<number | null>(null);
  const [now, setNow] = useState(Date.now);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    let disposed = false;
    let controller: AbortController | null = null;
    let pollingTimer: ReturnType<typeof setInterval> | undefined;
    let clockTimer: ReturnType<typeof setInterval> | undefined;
    let previousValues = new Map<string, number>();

    async function refresh() {
      // Prevent overlapping requests when a refresh takes longer than 10 seconds.
      if (disposed || document.hidden || controller) return;
      const request = new AbortController();
      controller = request;
      setLoading(true);
      try {
        const response = await fetch("/api/metrics", {
          signal: request.signal,
          cache: "no-store",
        });
        if (!response.ok) throw new Error(`Request failed (${response.status})`);
        const data: unknown = await response.json();
        if (!isMetrics(data)) throw new Error("Invalid metrics response");
        if (disposed || request.signal.aborted) return;

        const changed = new Set(data.filter((metric) =>
          previousValues.has(metric.name)
          && previousValues.get(metric.name) !== metric.value,
        ).map((metric) => metric.name));
        previousValues = new Map(data.map((metric) => [metric.name, metric.value]));
        const updatedAt = Date.now();
        setMetrics(data);
        setChangedNames(changed);
        setLastUpdated(updatedAt);
        setNow(updatedAt);
        setError(null);
      } catch (cause) {
        if (!disposed && !request.signal.aborted) {
          setError(cause instanceof Error ? cause.message : "Unable to load metrics");
        }
      } finally {
        // An aborted request must not clear a newer request's state.
        if (!disposed && controller === request) {
          controller = null;
          setLoading(false);
        }
      }
    }

    function stopTimers() {
      clearInterval(pollingTimer);
      clearInterval(clockTimer);
    }

    function handleVisibility() {
      stopTimers();
      if (document.hidden) {
        controller?.abort();
        controller = null;
        setLoading(false);
        return;
      }
      setNow(Date.now());
      void refresh();
      pollingTimer = setInterval(() => void refresh(), 10_000);
      clockTimer = setInterval(() => setNow(Date.now()), 1_000);
    }

    document.addEventListener("visibilitychange", handleVisibility);
    handleVisibility();
    return () => {
      disposed = true;
      stopTimers();
      controller?.abort();
      document.removeEventListener("visibilitychange", handleVisibility);
    };
  }, []);

  const secondsAgo = lastUpdated === null
    ? null
    : Math.max(0, Math.floor((now - lastUpdated) / 1_000));

  return (
    <section aria-label="Metrics" style={{ padding: 24, fontFamily: "system-ui, sans-serif" }}>
      <h2>Metrics</h2>
      <p>{secondsAgo === null ? "Waiting for metrics" : `Last updated ${secondsAgo} seconds ago`}</p>
      {loading && <p role="status">Refreshing metrics…</p>}
      {error && <p role="alert">Could not refresh metrics: {error}. Retrying automatically.</p>}
      {lastUpdated !== null && metrics.length === 0 && <p>No metrics available.</p>}
      <dl style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 16 }}>
        {metrics.map((metric) => {
          const changed = changedNames.has(metric.name);
          return (
            <div
              key={metric.name}
              data-changed={changed}
              style={{
                padding: 16,
                borderRadius: 8,
                border: `1px solid ${changed ? "#b45309" : "#cbd5e1"}`,
                background: changed ? "#fef3c7" : "#f8fafc",
                color: "#0f172a",
              }}
            >
              <dt>{metric.name}</dt>
              <dd style={{ margin: "8px 0 0", fontSize: 24, fontWeight: 600 }}>
                {metric.value.toLocaleString()} {metric.unit}
              </dd>
              {changed && <small>Changed since last refresh</small>}
            </div>
          );
        })}
      </dl>
    </section>
  );
}

export default MetricsPanel;

import { useId, useRef, useState } from 'react';
import type { FormEvent } from 'react';

type Values = {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
};

type Field = keyof Values;
type Errors = Partial<Record<Field, string>>;

const initialValues: Values = {
  name: '',
  email: '',
  password: '',
  confirmPassword: '',
  acceptTerms: false,
};

function validate(values: Values): Errors {
  const errors: Errors = {};
  if (!values.name.trim()) errors.name = 'Enter your name.';
  if (!values.email.trim()) {
    errors.email = 'Enter your email address.';
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) {
    errors.email = 'Enter a valid email address.';
  }
  if (!values.password) errors.password = 'Enter a password.';
  if (!values.confirmPassword) {
    errors.confirmPassword = 'Confirm your password.';
  } else if (values.password !== values.confirmPassword) {
    errors.confirmPassword = 'Passwords must match.';
  }
  if (!values.acceptTerms) errors.acceptTerms = 'Accept the terms to continue.';
  return errors;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

const textFields = [
  { name: 'name', label: 'Name', type: 'text', autoComplete: 'name' },
  { name: 'email', label: 'Email', type: 'email', autoComplete: 'email' },
  { name: 'password', label: 'Password', type: 'password', autoComplete: 'new-password' },
  { name: 'confirmPassword', label: 'Confirm password', type: 'password', autoComplete: 'new-password' },
] as const;

export function SignupForm() {
  const id = useId();
  const [values, setValues] = useState<Values>(initialValues);
  const [errors, setErrors] = useState<Errors>({});
  const [formError, setFormError] = useState('');
  const [success, setSuccess] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const submitting = useRef(false);

  function updateField<K extends Field>(field: K, value: Values[K]) {
    const next = { ...values, [field]: value };
    setValues(next);
    setSuccess('');
    setFormError('');
    setErrors((previous) => {
      const updated = { ...previous };
      delete updated[field];
      if (field === 'password' && (next.confirmPassword || previous.confirmPassword)) {
        updated.confirmPassword = validate(next).confirmPassword;
      }
      return updated;
    });
  }

  function validateField(field: Field) {
    const error = validate(values)[field];
    setErrors((previous) => ({ ...previous, [field]: previous[field] || error }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submitting.current) return;
    setSuccess('');
    setFormError('');
    const validationErrors = validate(values);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) return;

    submitting.current = true;
    setIsSubmitting(true);
    try {
      const response = await fetch('/api/signup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...values,
          name: values.name.trim(),
          email: values.email.trim(),
        }),
      });
      const data: unknown = await response.json().catch(() => null);
      if (isRecord(data) && isRecord(data.errors)) {
        const fieldErrors: Errors = {};
        const otherErrors: string[] = [];
        for (const [field, message] of Object.entries(data.errors)) {
          if (typeof message !== 'string' || !message) continue;
          if (Object.prototype.hasOwnProperty.call(initialValues, field)) {
            fieldErrors[field as Field] = message;
          } else {
            otherErrors.push(message);
          }
        }
        if (Object.keys(fieldErrors).length || otherErrors.length) {
          setErrors(fieldErrors);
          setFormError(otherErrors.join(' '));
          return;
        }
      }
      if (!response.ok) {
        setFormError('Unable to create your account. Please try again.');
        return;
      }
      if (
        !isRecord(data) ||
        !((typeof data.id === 'string' && data.id.trim() !== '') ||
          (typeof data.id === 'number' && Number.isFinite(data.id)))
      ) {
        setFormError('The server did not return an account id. Your account may have been created.');
        return;
      }
      setSuccess(`Account created successfully! Your account id is ${data.id}.`);
      setValues(initialValues);
      setErrors({});
    } catch {
      setFormError('Could not reach the server. Please check your connection and try again.');
    } finally {
      submitting.current = false;
      setIsSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate aria-busy={isSubmitting}>
      <fieldset disabled={isSubmitting}>
        <legend>Create an account</legend>
        {textFields.map((field) => (
          <div key={field.name}>
            <label htmlFor={`${id}-${field.name}`}>{field.label}</label>
            <input
              id={`${id}-${field.name}`}
              name={field.name}
              type={field.type}
              autoComplete={field.autoComplete}
              required
              value={values[field.name]}
              onChange={(event) => updateField(field.name, event.target.value)}
              onBlur={() => validateField(field.name)}
              aria-invalid={Boolean(errors[field.name])}
              aria-describedby={errors[field.name] ? `${id}-${field.name}-error` : undefined}
            />
            {errors[field.name] && (
              <p id={`${id}-${field.name}-error`} role="alert">{errors[field.name]}</p>
            )}
          </div>
        ))}
        <div>
          <label htmlFor={`${id}-acceptTerms`}>
            <input
              id={`${id}-acceptTerms`}
              name="acceptTerms"
              type="checkbox"
              required
              checked={values.acceptTerms}
              onChange={(event) => updateField('acceptTerms', event.target.checked)}
              onBlur={() => validateField('acceptTerms')}
              aria-invalid={Boolean(errors.acceptTerms)}
              aria-describedby={errors.acceptTerms ? `${id}-acceptTerms-error` : undefined}
            />
            I accept the terms
          </label>
          {errors.acceptTerms && (
            <p id={`${id}-acceptTerms-error`} role="alert">{errors.acceptTerms}</p>
          )}
        </div>
        <button type="submit" disabled={isSubmitting}>
          {isSubmitting ? 'Creating account…' : 'Sign up'}
        </button>
      </fieldset>
      {formError && <p role="alert">{formError}</p>}
      {success && <p role="status">{success}</p>}
    </form>
  );
}

export default SignupForm;

import { useId, useRef, useState } from 'react';
import type { FormEvent } from 'react';

type Values = {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
};
type Field = keyof Values;
type Errors = Partial<Record<Field, string>>;

const initialValues: Values = {
  name: '',
  email: '',
  password: '',
  confirmPassword: '',
  acceptTerms: false,
};

function validate(values: Values): Errors {
  const errors: Errors = {};
  if (!values.name.trim()) errors.name = 'Enter your name.';
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) {
    errors.email = 'Enter a valid email address.';
  }
  if (values.password.length < 8) {
    errors.password = 'Use at least 8 characters.';
  }
  if (!values.confirmPassword) {
    errors.confirmPassword = 'Confirm your password.';
  } else if (values.password !== values.confirmPassword) {
    errors.confirmPassword = 'Passwords must match.';
  }
  if (!values.acceptTerms) errors.acceptTerms = 'Accept the terms to continue.';
  return errors;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

const textFields = [
  { field: 'name', label: 'Name', type: 'text', autoComplete: 'name' },
  { field: 'email', label: 'Email', type: 'email', autoComplete: 'email' },
  { field: 'password', label: 'Password', type: 'password', autoComplete: 'new-password' },
  { field: 'confirmPassword', label: 'Confirm password', type: 'password', autoComplete: 'new-password' },
] as const;

export function SignupForm() {
  const prefix = useId();
  const [values, setValues] = useState<Values>(initialValues);
  const [errors, setErrors] = useState<Errors>({});
  const [formError, setFormError] = useState('');
  const [accountId, setAccountId] = useState<string | number | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const submitting = useRef(false);

  function updateField<K extends Field>(field: K, value: Values[K]) {
    setValues((previous) => ({ ...previous, [field]: value }));
    setErrors((previous) => ({
      ...previous,
      [field]: undefined,
      ...(field === 'password' ? { confirmPassword: undefined } : {}),
    }));
  }

  function validateField(field: Field) {
    setErrors((previous) => ({ ...previous, [field]: validate(values)[field] }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submitting.current) return;
    setAccountId(null);
    setFormError('');
    const validationErrors = validate(values);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) return;

    submitting.current = true;
    setIsSubmitting(true);
    try {
      const response = await fetch('/api/signup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...values, name: values.name.trim(), email: values.email.trim() }),
      });
      const data: unknown = await response.json();
      if (isRecord(data) && isRecord(data.errors)) {
        const serverErrors: Errors = {};
        let hasUnknownError = false;
        for (const [field, message] of Object.entries(data.errors)) {
          if (typeof message !== 'string' || !message) continue;
          if (Object.prototype.hasOwnProperty.call(initialValues, field)) {
            serverErrors[field as Field] = message;
          } else {
            hasUnknownError = true;
          }
        }
        if (Object.keys(serverErrors).length > 0 || hasUnknownError) {
          setErrors(serverErrors);
          if (hasUnknownError) setFormError('Unable to create your account. Please review your details and try again.');
          return;
        }
      }
      if (!response.ok) {
        setFormError('Unable to create your account. Please try again.');
        return;
      }
      if (!isRecord(data) || !(
        (typeof data.id === 'string' && data.id.trim().length > 0) ||
        (typeof data.id === 'number' && Number.isFinite(data.id))
      )) {
        setFormError('The server did not return an account ID. Your account may have been created.');
        return;
      }
      setAccountId(data.id);
      setValues({ ...initialValues });
      setErrors({});
    } catch {
      setFormError('Unable to confirm account creation. Please check your connection and try again.');
    } finally {
      submitting.current = false;
      setIsSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate aria-busy={isSubmitting}>
      <h2>Create an account</h2>
      {accountId !== null && <p role="status">Account created successfully! Your account ID is {accountId}.</p>}
      {formError && <p role="alert">{formError}</p>}
      <fieldset disabled={isSubmitting}>
        <legend>Account details</legend>
        {textFields.map(({ field, label, type, autoComplete }) => (
          <div key={field}>
            <label htmlFor={`${prefix}-${field}`}>{label}</label>
            <input
              id={`${prefix}-${field}`}
              name={field}
              type={type}
              autoComplete={autoComplete}
              required
              minLength={field === 'password' ? 8 : undefined}
              value={values[field]}
              onChange={(event) => updateField(field, event.target.value)}
              onBlur={() => validateField(field)}
              aria-invalid={Boolean(errors[field])}
              aria-describedby={errors[field] ? `${prefix}-${field}-error` : undefined}
            />
            {errors[field] && <p id={`${prefix}-${field}-error`} role="alert">{errors[field]}</p>}
          </div>
        ))}
        <div>
          <label htmlFor={`${prefix}-acceptTerms`}>
            <input
              id={`${prefix}-acceptTerms`}
              name="acceptTerms"
              type="checkbox"
              required
              checked={values.acceptTerms}
              onChange={(event) => updateField('acceptTerms', event.target.checked)}
              onBlur={() => validateField('acceptTerms')}
              aria-invalid={Boolean(errors.acceptTerms)}
              aria-describedby={errors.acceptTerms ? `${prefix}-acceptTerms-error` : undefined}
            />
            I accept the terms
          </label>
          {errors.acceptTerms && <p id={`${prefix}-acceptTerms-error`} role="alert">{errors.acceptTerms}</p>}
        </div>
        <button type="submit" disabled={isSubmitting}>
          {isSubmitting ? 'Creating account…' : 'Create account'}
        </button>
      </fieldset>
    </form>
  );
}

