import { useEffect, useRef, useState, type FormEvent } from 'react';

export interface ChatRoomProps {
  roomId: string;
}

interface Message {
  id: string;
  author: string;
  text: string;
  sentAt: string | number;
}

type ConnectionStatus = 'connecting' | 'connected' | 'reconnecting';

function isMessage(value: unknown): value is Message {
  if (typeof value !== 'object' || value === null) return false;
  const message = value as Record<string, unknown>;
  return (
    typeof message.id === 'string' &&
    typeof message.author === 'string' &&
    typeof message.text === 'string' &&
    (typeof message.sentAt === 'string' ||
      (typeof message.sentAt === 'number' && Number.isFinite(message.sentAt)))
  );
}

// A keyed session resets messages, draft, and connection state on room changes.
export function ChatRoom({ roomId }: ChatRoomProps) {
  return <RoomSession key={roomId} roomId={roomId} />;
}

function RoomSession({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [draft, setDraft] = useState('');
  const [status, setStatus] = useState<ConnectionStatus>('connecting');
  const [sendError, setSendError] = useState<string | null>(null);
  const socketRef = useRef<WebSocket | null>(null);
  const messageListRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    let disposed = false;
    let retryTimer: ReturnType<typeof setTimeout> | undefined;
    let retryCount = 0;
    let activeSocket: WebSocket | null = null;

    function scheduleReconnect() {
      if (disposed || retryTimer !== undefined) return;
      setStatus('reconnecting');
      const delay = Math.min(1000 * 2 ** retryCount, 30_000);
      retryCount = Math.min(retryCount + 1, 5);
      retryTimer = setTimeout(() => {
        retryTimer = undefined;
        connect();
      }, delay);
    }

    function connect() {
      if (disposed) return;

      let socket: WebSocket;
      try {
        socket = new WebSocket(
          `wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`,
        );
      } catch {
        scheduleReconnect();
        return;
      }

      activeSocket = socket;
      socketRef.current = socket;
      const isCurrent = () => !disposed && activeSocket === socket;

      socket.onopen = () => {
        if (!isCurrent()) return;
        retryCount = 0;
        setStatus('connected');
        setSendError(null);
      };

      socket.onmessage = (event: MessageEvent<unknown>) => {
        if (!isCurrent() || typeof event.data !== 'string') return;
        try {
          const message: unknown = JSON.parse(event.data);
          if (!isMessage(message)) return;
          setMessages((previous) =>
            previous.some((item) => item.id === message.id)
              ? previous
              : [...previous, message],
          );
        } catch {
          // Ignore malformed frames without interrupting the conversation.
        }
      };

      socket.onerror = () => {
        if (!isCurrent()) return;
        setStatus('reconnecting');
        // The close event schedules the retry, avoiding duplicate connections.
        socket.close();
      };

      socket.onclose = () => {
        if (!isCurrent()) return;
        socketRef.current = null;
        activeSocket = null;
        scheduleReconnect();
      };
    }

    connect();

    return () => {
      disposed = true;
      clearTimeout(retryTimer);
      socketRef.current = null;
      if (activeSocket) {
        activeSocket.onopen = null;
        activeSocket.onmessage = null;
        activeSocket.onerror = null;
        activeSocket.onclose = null;
        activeSocket.close();
        activeSocket = null;
      }
    };
  }, [roomId]);

  useEffect(() => {
    const list = messageListRef.current;
    if (list) list.scrollTop = list.scrollHeight;
  }, [messages]);

  function sendMessage(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const text = draft.trim();
    if (!text) return;

    const socket = socketRef.current;
    if (!socket || socket.readyState !== WebSocket.OPEN) {
      setSendError('You are disconnected. Try sending again after reconnecting.');
      return;
    }

    try {
      // The server supplies the message ID, author, and timestamp in its echo.
      socket.send(JSON.stringify({ text }));
      setDraft('');
      setSendError(null);
    } catch {
      setSendError('Message could not be sent. Please try again.');
    }
  }

  return (
    <section aria-label={`Chat room ${roomId}`}>
      <h2>Room {roomId}</h2>
      <div role="status" aria-live="polite">
        {status === 'reconnecting'
          ? 'Reconnecting…'
          : status === 'connecting'
            ? 'Connecting…'
            : 'Connected'}
      </div>
      <div
        ref={messageListRef}
        role="log"
        aria-label="Messages"
        aria-live="polite"
        aria-relevant="additions"
        tabIndex={0}
        style={{ maxHeight: '24rem', overflowY: 'auto' }}
      >
        {messages.length === 0 ? (
          <p>No messages yet.</p>
        ) : (
          <ul>
            {messages.map((message) => (
              <li key={message.id}>
                <strong>{message.author}</strong>{' '}
                <span>{message.sentAt}</span>
                <p style={{ whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }}>
                  {message.text}
                </p>
              </li>
            ))}
          </ul>
        )}
      </div>
      <form onSubmit={sendMessage}>
        <label>
          Message
          <input
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            autoComplete="off"
          />
        </label>
        <button type="submit" disabled={status !== 'connected' || !draft.trim()}>
          Send
        </button>
        {sendError && <p role="alert">{sendError}</p>}
      </form>
    </section>
  );
}

