import { useEffect, useRef, useState, type FormEvent } from 'react';

const INITIAL_RETRY_DELAY_MS = 1_000;
const MAX_RETRY_DELAY_MS = 30_000;

export interface ChatRoomProps {
  roomId: string;
}

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string;
}

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== 'object' || value === null) return false;
  const message = value as Record<string, unknown>;
  return (
    typeof message.id === 'string' &&
    typeof message.author === 'string' &&
    typeof message.text === 'string' &&
    typeof message.sentAt === 'string'
  );
}

function parseMessage(data: string): ChatMessage | null {
  try {
    const value: unknown = JSON.parse(data);
    return isChatMessage(value) ? value : null;
  } catch {
    return null;
  }
}

function RoomSession({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState('');
  const [status, setStatus] = useState<'connecting' | 'connected' | 'reconnecting'>('connecting');
  const [sendError, setSendError] = useState<string | null>(null);
  const socketRef = useRef<WebSocket | null>(null);
  const newestMessageRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    let disposed = false;
    let retryTimer: ReturnType<typeof setTimeout> | undefined;
    let retryDelay = INITIAL_RETRY_DELAY_MS;

    function scheduleReconnect() {
      if (disposed || retryTimer !== undefined) return;
      setStatus('reconnecting');
      const delay = retryDelay;
      retryDelay = Math.min(retryDelay * 2, MAX_RETRY_DELAY_MS);
      retryTimer = setTimeout(() => {
        retryTimer = undefined;
        connect();
      }, delay);
    }

    function connect() {
      if (disposed) return;
      let socket: WebSocket;
      try {
        socket = new WebSocket(`wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`);
      } catch {
        scheduleReconnect();
        return;
      }
      socketRef.current = socket;
      const isCurrent = () => !disposed && socketRef.current === socket;

      socket.onopen = () => {
        if (!isCurrent()) return;
        retryDelay = INITIAL_RETRY_DELAY_MS;
        setStatus('connected');
      };

      socket.onmessage = (event: MessageEvent) => {
        if (!isCurrent() || typeof event.data !== 'string') return;
        const message = parseMessage(event.data);
        if (!message) return;
        setMessages((previous) =>
          previous.some((item) => item.id === message.id)
            ? previous
            : [...previous, message],
        );
      };

      socket.onclose = () => {
        if (!isCurrent()) return;
        socketRef.current = null;
        scheduleReconnect();
      };

      socket.onerror = () => {
        if (!isCurrent()) return;
        setStatus('reconnecting');
        socket.close(); // The close event schedules a single retry.
      };
    }

    connect();
    return () => {
      disposed = true;
      if (retryTimer !== undefined) clearTimeout(retryTimer);
      const socket = socketRef.current;
      socketRef.current = null;
      if (socket) {
        socket.onopen = null;
        socket.onmessage = null;
        socket.onerror = null;
        socket.onclose = null;
        socket.close();
      }
    };
  }, [roomId]);

  useEffect(() => {
    newestMessageRef.current?.scrollIntoView({ block: 'end' });
  }, [messages]);

  function sendMessage(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const text = draft.trim();
    if (!text) return;
    const socket = socketRef.current;
    if (!socket || socket.readyState !== WebSocket.OPEN) {
      setSendError('Your message was not sent. Wait for the connection and try again.');
      return;
    }
    try {
      // The server supplies identity, timestamps, and the canonical message echo.
      socket.send(JSON.stringify({ text }));
      setDraft('');
      setSendError(null);
    } catch {
      setSendError('Your message was not sent. Please try again.');
    }
  }

  return (
    <section aria-label={`Chat room ${roomId}`}>
      <h2>Room {roomId}</h2>
      <div role="status">
        {status === 'connecting' && 'Connecting…'}
        {status === 'reconnecting' && 'Reconnecting…'}
      </div>
      <div
        role="log"
        aria-label="Messages"
        aria-live="polite"
        aria-relevant="additions"
        tabIndex={0}
        style={{ maxHeight: '24rem', overflowY: 'auto', overflowWrap: 'anywhere' }}
      >
        {messages.map((message) => (
          <article key={message.id}>
            <strong>{message.author}</strong>{' '}
            <time dateTime={message.sentAt}>{message.sentAt}</time>
            <p style={{ whiteSpace: 'pre-wrap' }}>{message.text}</p>
          </article>
        ))}
        <div ref={newestMessageRef} />
      </div>
      <form onSubmit={sendMessage}>
        <label>
          Message
          <input
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            autoComplete="off"
          />
        </label>
        <button type="submit" disabled={status !== 'connected' || !draft.trim()}>
          Send
        </button>
        {sendError && <p role="alert">{sendError}</p>}
      </form>
    </section>
  );
}

export function ChatRoom({ roomId }: ChatRoomProps) {
  // A new session clears room-specific state immediately when switching rooms.
  return <RoomSession key={roomId} roomId={roomId} />;
}

