import { useEffect, useState, type FormEvent } from 'react';

type Todo = { id: string; text: string; completed: boolean };
type Filter = 'all' | 'active' | 'done';

const STORAGE_KEY = 'todo-board-items';

function loadTodos(): Todo[] {
  try {
    const stored: unknown = JSON.parse(
      window.localStorage.getItem(STORAGE_KEY) ?? '[]',
    );
    if (!Array.isArray(stored)) return [];

    const ids = new Set<string>();
    return stored.filter((item: unknown): item is Todo => {
      if (
        typeof item !== 'object' || item === null ||
        !('id' in item) || typeof item.id !== 'string' || !item.id ||
        !('text' in item) || typeof item.text !== 'string' || !item.text.trim() ||
        !('completed' in item) || typeof item.completed !== 'boolean' ||
        ids.has(item.id)
      ) return false;
      ids.add(item.id);
      return true;
    });
  } catch {
    return [];
  }
}

export function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(loadTodos);
  const [newText, setNewText] = useState('');
  const [filter, setFilter] = useState<Filter>('all');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editText, setEditText] = useState('');
  const [storageError, setStorageError] = useState(false);

  useEffect(() => {
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
      setStorageError(false);
    } catch {
      setStorageError(true);
    }
  }, [todos]);

  const remaining = todos.filter((todo) => !todo.completed).length;
  const visibleTodos = todos.filter((todo) =>
    filter === 'all' || (filter === 'done' ? todo.completed : !todo.completed),
  );

  function addTodo(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const text = newText.trim();
    if (!text) return;
    const todo: Todo = { id: crypto.randomUUID(), text, completed: false };
    setTodos((current) => [...current, todo]);
    setNewText('');
  }

  function saveEdit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const text = editText.trim();
    if (!text) return;
    setTodos((current) => current.map((todo) =>
      todo.id === editingId ? { ...todo, text } : todo,
    ));
    setEditingId(null);
  }

  function moveTodo(id: string, direction: -1 | 1) {
    const index = visibleTodos.findIndex((todo) => todo.id === id);
    const neighbor = visibleTodos[index + direction];
    if (index < 0 || !neighbor) return;

    // Swap visible neighbors while preserving hidden items' positions.
    setTodos((current) => {
      const from = current.findIndex((todo) => todo.id === id);
      const to = current.findIndex((todo) => todo.id === neighbor.id);
      if (from < 0 || to < 0) return current;
      const reordered = [...current];
      [reordered[from], reordered[to]] = [reordered[to], reordered[from]];
      return reordered;
    });
