      </form>

      <p role="status">{remaining} {remaining === 1 ? 'item' : 'items'} remaining</p>
      {storageError && <p role="alert">Changes could not be saved to this browser. Your tasks are still available until you leave this page.</p>}

      <div role="group" aria-label="Filter tasks" style={{ display: 'flex', gap: 8 }}>
        {(['all', 'active', 'done'] as const).map((option) => (
          <button key={option} type="button" aria-pressed={filter === option} onClick={() => {
            setFilter(option);
            setEditingId(null);
          }}>
            {option === 'all' ? 'All' : option === 'active' ? 'Active' : 'Done'}
          </button>
        ))}
      </div>

      {visibleTodos.length === 0 ? (
        <p>{todos.length === 0 ? 'No tasks yet. Add your first task above.' : `No ${filter} tasks.`}</p>
      ) : (
        <ul style={{ listStyle: 'none', padding: 0 }}>
          {visibleTodos.map((todo, index) => (
            <li key={todo.id} style={{ padding: '1rem 0', borderBottom: '1px solid #ccc', overflowWrap: 'anywhere' }}>
              <label>
                <input type="checkbox" checked={todo.completed} onChange={() => {
                  setTodos((current) => current.map((item) =>
                    item.id === todo.id ? { ...item, completed: !item.completed } : item,
                  ));
                }} />{' '}
                <span style={{ textDecoration: todo.completed ? 'line-through' : undefined }}>{todo.text}</span>
              </label>

              {editingId === todo.id ? (
                <form onSubmit={saveEdit} style={{ marginTop: 8 }}>
                  <label>
                    Edit task{' '}
                    <input autoFocus value={editText} onChange={(event) => setEditText(event.target.value)} onKeyDown={(event) => {
                      if (event.key === 'Escape') {
                        event.preventDefault();
                        setEditingId(null);
                      }
                    }} />
                  </label>{' '}
                  <button type="submit" disabled={!editText.trim()}>Save</button>{' '}
                  <button type="button" onClick={() => setEditingId(null)}>Cancel</button>
                </form>
              ) : (
                <button type="button" aria-label={`Edit ${todo.text}`} onClick={() => {
                  setEditingId(todo.id);
                  setEditText(todo.text);
                }} style={{ marginLeft: 8 }}>Edit</button>
              )}

              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 8 }}>
                <button type="button" aria-label={`Move ${todo.text} up`} disabled={index === 0} onClick={() => moveTodo(todo.id, -1)}>Move up</button>
                <button type="button" aria-label={`Move ${todo.text} down`} disabled={index === visibleTodos.length - 1} onClick={() => moveTodo(todo.id, 1)}>Move down</button>
                <button type="button" aria-label={`Delete ${todo.text}`} onClick={() => {
                  setTodos((current) => current.filter((item) => item.id !== todo.id));
                  if (editingId === todo.id) setEditingId(null);
                }}>Delete</button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

