import { useEffect, useState } from "react";
import type { UserProfile } from "./ProfileEditor";

export interface UserProfilesResult {
  profiles: UserProfile[];
  isLoading: boolean;
  error: Error | null;
}

function isUserProfile(value: unknown): value is UserProfile {
  if (typeof value !== "object" || value === null) return false;
  return (
    "id" in value && typeof value.id === "string" &&
    "displayName" in value && typeof value.displayName === "string" &&
    "bio" in value && typeof value.bio === "string" &&
    "avatarUrl" in value && typeof value.avatarUrl === "string"
  );
}

/** Loads profiles in the requested order; any failed request produces an error. */
export function useUserProfiles(ids: readonly string[]): UserProfilesResult {
  // Compare ID values so inline arrays do not trigger repeated requests.
  const requestKey = JSON.stringify(ids);
  const [state, setState] = useState<UserProfilesResult & { key: string }>({
    key: requestKey,
    profiles: [],
    isLoading: ids.length > 0,
    error: null,
  });

  useEffect(() => {
    const requestedIds: string[] = JSON.parse(requestKey);
    const controller = new AbortController();
    let active = true;
    setState({ key: requestKey, profiles: [], isLoading: requestedIds.length > 0, error: null });

    async function load() {
      try {
        const profiles = await Promise.all(requestedIds.map(async (id) => {
          const response = await fetch(`/api/users/${encodeURIComponent(id)}`, {
            signal: controller.signal,
          });
          if (!response.ok) {
            throw new Error(`Unable to load profile ${id} (${response.status}).`);
          }
          const profile: unknown = await response.json();
          if (!isUserProfile(profile) || profile.id !== id) {
            throw new Error(`Invalid profile response for ${id}.`);
          }
          return profile;
        }));
        if (active) setState({ key: requestKey, profiles, isLoading: false, error: null });
      } catch (cause) {
        if (active) {
          controller.abort();
          setState({
            key: requestKey,
            profiles: [],
            isLoading: false,
            error: cause instanceof Error ? cause : new Error("Unable to load profiles."),
          });
        }
      }
    }

    void load();
    return () => {
      active = false;
      controller.abort();
    };
  }, [requestKey]);

  if (state.key !== requestKey) {
    return { profiles: [], isLoading: ids.length > 0, error: null };
  }
  return { profiles: state.profiles, isLoading: state.isLoading, error: state.error };
}

