import { useId, useRef, useState } from "react";
import type { FormEvent } from "react";

export interface UserProfile {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: UserProfile;
  onSave: (user: UserProfile) => Promise<void>;
}

export function ProfileEditor(props: ProfileEditorProps) {
  // A different incoming profile starts a fresh editing session.
  return <ProfileEditorForm key={JSON.stringify(props.user)} {...props} />;
}

function ProfileEditorForm({ user, onSave }: ProfileEditorProps) {
  const [saved, setSaved] = useState(user);
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const saving = useRef(false);
  const fieldId = useId();
  const isDirty = displayName !== saved.displayName || bio !== saved.bio;

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (saving.current || !isDirty) return;

    const updated = { ...saved, displayName, bio };
    saving.current = true;
    setIsSaving(true);
    setError(null);
    try {
      await onSave(updated);
      setSaved(updated);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Unable to save profile.");
    } finally {
      saving.current = false;
      setIsSaving(false);
    }
  }

  function reset() {
    setDisplayName(saved.displayName);
    setBio(saved.bio);
    setError(null);
  }

  return (
    <form onSubmit={handleSubmit} aria-busy={isSaving}>
      {user.avatarUrl && <img src={user.avatarUrl} alt={`${saved.displayName}'s avatar`} />}
      <label htmlFor={`${fieldId}-name`}>Display name</label>
      <input
        id={`${fieldId}-name`}
        value={displayName}
        onChange={(event) => setDisplayName(event.target.value)}
        disabled={isSaving}
      />
      <label htmlFor={`${fieldId}-bio`}>Bio</label>
      <textarea
        id={`${fieldId}-bio`}
        value={bio}
        onChange={(event) => setBio(event.target.value)}
        disabled={isSaving}
      />
      <p role="status">{isDirty ? "Unsaved changes" : "No unsaved changes"}</p>
      {error && <p role="alert">{error}</p>}
      <button type="submit" disabled={isSaving || !isDirty}>
        {isSaving ? "Saving…" : "Save"}
      </button>
      <button type="button" onClick={reset} disabled={isSaving || !isDirty}>
        Reset
      </button>
    </form>
  );
}

