import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UserProfilesResult {
  profiles: User[];
  loading: boolean;
  error: Error | null;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  return (
    "id" in value && typeof value.id === "string" &&
    "displayName" in value && typeof value.displayName === "string" &&
    "bio" in value && typeof value.bio === "string" &&
    "avatarUrl" in value && typeof value.avatarUrl === "string"
  );
}

/** Fetches profiles concurrently and returns them in the requested ID order. */
export function useUserProfiles(ids: readonly string[]): UserProfilesResult {
  // Compare values so inline arrays do not restart requests on every render.
  const requestKey = JSON.stringify(ids);
  const [state, setState] = useState<UserProfilesResult & { key: string }>({
    key: requestKey,
    profiles: [],
    loading: ids.length > 0,
    error: null,
  });

  useEffect(() => {
    const requestedIds: string[] = JSON.parse(requestKey);
    const controller = new AbortController();
    let active = true;
    setState({ key: requestKey, profiles: [], loading: requestedIds.length > 0, error: null });

    async function load() {
      try {
        const uniqueIds = [...new Set(requestedIds)];
        const users = await Promise.all(uniqueIds.map(async (id) => {
          const response = await fetch(`/api/users/${encodeURIComponent(id)}`, {
            signal: controller.signal,
          });
          if (!response.ok) throw new Error(`Unable to load profile ${id} (${response.status}).`);
          const profile: unknown = await response.json();
          if (!isUser(profile) || profile.id !== id) {
            throw new Error(`Invalid profile returned for ${id}.`);
          }
          return profile;
        }));
        const byId = new Map(users.map((user) => [user.id, user]));
        if (active) {
          setState({
            key: requestKey,
            profiles: requestedIds.map((id) => {
              const profile = byId.get(id);
              if (!profile) throw new Error(`Missing profile for ${id}.`);
              return profile;
            }),
            loading: false,
            error: null,
          });
        }
      } catch (cause) {
        if (active) {
          controller.abort();
          setState({
            key: requestKey,
            profiles: [],
            loading: false,
            error: cause instanceof Error ? cause : new Error("Unable to load profiles."),
          });
        }
      }
    }

    if (requestedIds.length > 0) void load();
    return () => { active = false; controller.abort(); };
  }, [requestKey]);

  if (state.key !== requestKey) {
    return { profiles: [], loading: ids.length > 0, error: null };
  }
  return { profiles: state.profiles, loading: state.loading, error: state.error };
}

export default useUserProfiles;

import { useEffect, useId, useRef, useState, type FormEvent } from "react";

export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: User;
  onSave: (user: User) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  // Incoming profile changes start a fresh editing session, even for the same ID.
  const sessionKey = JSON.stringify([
    user.id, user.displayName, user.bio, user.avatarUrl,
  ]);
  return <ProfileForm key={sessionKey} user={user} onSave={onSave} />;
}

function ProfileForm({ user, onSave }: ProfileEditorProps) {
  const [saved, setSaved] = useState(() => ({ ...user }));
  const [draft, setDraft] = useState(() => ({ ...user }));
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const inFlight = useRef(false);
  const mounted = useRef(false);
  const fieldId = useId();
  const dirty = draft.displayName !== saved.displayName || draft.bio !== saved.bio;

  useEffect(() => {
    mounted.current = true;
    return () => { mounted.current = false; };
  }, []);

  async function handleSave(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (inFlight.current || !dirty) return;
    inFlight.current = true;
    setSaving(true);
    setError(null);
    const snapshot = { ...draft };
    try {
      await onSave({ ...snapshot });
      if (mounted.current) setSaved(snapshot);
    } catch (cause) {
      if (mounted.current) {
        setError(cause instanceof Error ? cause.message : "Unable to save profile.");
      }
    } finally {
      inFlight.current = false;
      if (mounted.current) setSaving(false);
    }
  }

  return (
    <form onSubmit={handleSave} aria-label="Edit profile" aria-busy={saving}>
      {draft.avatarUrl && <img src={draft.avatarUrl} alt="Profile avatar" width={80} height={80} />}
      <div>
        <label htmlFor={`${fieldId}-name`}>Display name</label>
        <input
          id={`${fieldId}-name`}
          name="displayName"
          value={draft.displayName}
          disabled={saving}
          onChange={(event) => setDraft({ ...draft, displayName: event.target.value })}
        />
      </div>
      <div>
        <label htmlFor={`${fieldId}-bio`}>Bio</label>
        <textarea
          id={`${fieldId}-bio`}
          name="bio"
          value={draft.bio}
          disabled={saving}
          onChange={(event) => setDraft({ ...draft, bio: event.target.value })}
        />
      </div>
      <p role="status">{dirty ? "Unsaved changes" : "No unsaved changes"}</p>
      {error !== null && <p role="alert">{error}</p>}
      <button type="submit" disabled={saving || !dirty}>
        {saving ? "Saving…" : "Save"}
      </button>
      <button
        type="button"
        disabled={saving || !dirty}
        onClick={() => { setDraft({ ...saved }); setError(null); }}
      >
        Reset
      </button>
    </form>
  );
}

