import SwiftUI

struct StopwatchLap: Identifiable {
    let id: Int
    let splitTime: TimeInterval
}

@MainActor
final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsedTime: TimeInterval = 0
    @Published private(set) var isRunning = false
    @Published private(set) var laps: [StopwatchLap] = []

    private var timer: Timer?
    private var startedAt: TimeInterval?
    private var accumulatedTime: TimeInterval = 0
    private var lastLapTime: TimeInterval = 0

    func start() {
        guard !isRunning else { return }
        startedAt = ProcessInfo.processInfo.systemUptime
        isRunning = true

        let timer = Timer(timeInterval: 0.01, repeats: true) { [weak self] _ in
            Task { @MainActor [weak self] in
                self?.updateElapsedTime()
            }
        }
        self.timer = timer
        RunLoop.main.add(timer, forMode: .common)
    }

    func stop() {
        guard isRunning else { return }
        updateElapsedTime()
        accumulatedTime = elapsedTime
        startedAt = nil
        isRunning = false
        timer?.invalidate()
        timer = nil
    }

    func reset() {
        stop()
        accumulatedTime = 0
        elapsedTime = 0
        lastLapTime = 0
        laps.removeAll()
    }

    func lap() {
        guard isRunning else { return }
        updateElapsedTime()
        laps.append(StopwatchLap(id: laps.count + 1, splitTime: elapsedTime - lastLapTime))
        lastLapTime = elapsedTime
    }

    static func formattedTime(_ interval: TimeInterval) -> String {
        let hundredths = Int(max(0, interval) * 100)
        let minutes = hundredths / 6_000
        let seconds = (hundredths / 100) % 60
        let fraction = hundredths % 100
        func padded(_ value: Int) -> String {
            value < 10 ? "0\(value)" : String(value)
        }
        return "\(padded(minutes)):\(padded(seconds)).\(padded(fraction))"
    }

    private func updateElapsedTime() {
        guard let startedAt else { return }
        // Measure elapsed time independently of timer delivery to avoid drift.
        elapsedTime = accumulatedTime + ProcessInfo.processInfo.systemUptime - startedAt
    }

    deinit {
        timer?.invalidate()
    }
}

@MainActor
struct Stopwatch: View {
    @StateObject private var model = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 24) {
            Text("Stopwatch")
                .font(.title2.bold())

            Text(StopwatchViewModel.formattedTime(model.elapsedTime))
                .font(.system(size: 48, weight: .light, design: .monospaced))
                .monospacedDigit()
                .minimumScaleFactor(0.5)
                .lineLimit(1)
                .accessibilityLabel("Elapsed time")
                .accessibilityValue(StopwatchViewModel.formattedTime(model.elapsedTime))

            HStack {
                Button("Start", action: model.start)
                    .disabled(model.isRunning)
                Button("Stop", action: model.stop)
                    .disabled(!model.isRunning)
                Button("Reset", action: model.reset)
                    .disabled(model.elapsedTime == 0 && !model.isRunning && model.laps.isEmpty)
                Button("Lap", action: model.lap)
                    .disabled(!model.isRunning)
            }
            .buttonStyle(.bordered)

            List {
                if model.laps.isEmpty {
                    Text("Recorded laps will appear here.")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(model.laps) { lap in
                        HStack {
                            Text("Lap \(lap.id)")
                            Spacer()
                            Text(StopwatchViewModel.formattedTime(lap.splitTime))
                                .monospacedDigit()
                        }
                        .padding(.vertical, 4)
                        .accessibilityElement(children: .combine)
                    }
                }
            }
            .accessibilityLabel("Lap split times")
        }
        .padding()
        .onDisappear { model.stop() }
    }
}

import Foundation
import SwiftUI

struct SearchResult: Decodable, Identifiable {
    let id: String
    let title: String
    let subtitle: String
}

@MainActor
final class SearchViewModel: ObservableObject {
    enum State {
        case idle
        case loading
        case loaded([SearchResult])
        case failed(String)
    }

    @Published var query = ""
    @Published private(set) var state: State = .idle

    private let session: URLSession
    private let debounceDelay: Duration = .milliseconds(300)

    init(session: URLSession = .shared) {
        self.session = session
    }

    func search(for query: String) async {
        guard query == self.query, !Task.isCancelled else { return }
        let term = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !term.isEmpty else {
            state = .idle
            return
        }

        state = .loading

        do {
            try await Task.sleep(for: debounceDelay)
            try Task.checkCancellation()

            var components = URLComponents()
            components.scheme = "https"
            components.host = "api.example.com"
            components.path = "/search"
            components.queryItems = [URLQueryItem(name: "q", value: term)]
            guard let url = components.url else {
                throw URLError(.badURL)
            }

            let (data, response) = try await session.data(from: url)
            try Task.checkCancellation()
            guard let response = response as? HTTPURLResponse,
                  (200..<300).contains(response.statusCode) else {
                throw URLError(.badServerResponse)
            }

            let results = try JSONDecoder().decode([SearchResult].self, from: data)
            guard query == self.query, !Task.isCancelled else { return }
            state = .loaded(results)
        } catch {
            guard query == self.query, !Task.isCancelled else { return }
            if error is CancellationError || (error as? URLError)?.code == .cancelled {
                return
            }
            state = .failed("Search failed. \(error.localizedDescription)")
        }
    }
}

@MainActor
struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        VStack(spacing: 16) {
            TextField("Search", text: $viewModel.query)
                .textFieldStyle(.roundedBorder)
                .accessibilityLabel("Search")

            Group {
                switch viewModel.state {
                case .idle:
                    message("Enter a search term to find results.")
                case .loading:
                    ProgressView("Searching…")
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                case .loaded(let results):
                    if results.isEmpty {
                        message("No results found.")
                    } else {
                        List(results) { result in
                            VStack(alignment: .leading, spacing: 4) {
                                Text(result.title)
                                    .font(.headline)
                                Text(result.subtitle)
                                    .foregroundStyle(.secondary)
                                Text("ID: \(result.id)")
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                            }
                            .padding(.vertical, 4)
                        }
                    }
                case .failed(let error):
                    message(error)
                }
            }
        }
        .padding()
        .task(id: viewModel.query) {
            await viewModel.search(for: viewModel.query)
        }
    }

    private func message(_ text: String) -> some View {
        Text(text)
            .foregroundStyle(.secondary)
            .multilineTextAlignment(.center)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

import Foundation
import SwiftUI

struct SearchResult: Decodable, Identifiable {
    let id: String
    let title: String
    let subtitle: String
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query = ""
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private let session: URLSession

    init(session: URLSession = .shared) {
        self.session = session
    }

    func search() async {
        let originalQuery = query
        let searchTerm = originalQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !Task.isCancelled else { return }

        results = []
        errorMessage = nil
        isLoading = !searchTerm.isEmpty
        guard !searchTerm.isEmpty else { return }

        do {
            try await Task.sleep(for: .milliseconds(300))
            var components = URLComponents(string: "https://api.example.com/search")
            components?.queryItems = [URLQueryItem(name: "q", value: searchTerm)]
            guard let url = components?.url else { throw URLError(.badURL) }

            let (data, response) = try await session.data(from: url)
            try Task.checkCancellation()
            guard let response = response as? HTTPURLResponse,
                  (200..<300).contains(response.statusCode) else {
                throw URLError(.badServerResponse)
            }

            // The endpoint is expected to return an array of {id, title, subtitle} objects.
            let decodedResults = try JSONDecoder().decode([SearchResult].self, from: data)
            guard !Task.isCancelled, query == originalQuery else { return }
            results = decodedResults
            isLoading = false
        } catch {
            // A superseded search must never overwrite the current search's state.
            guard !Task.isCancelled, query == originalQuery else { return }
            isLoading = false
            errorMessage = "Unable to load results. \(error.localizedDescription)"
        }
    }
}

@MainActor
struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        VStack(spacing: 12) {
