    func reset() {
        stop()
        elapsedTime = 0
        accumulatedTime = 0
        lastLapTime = 0
        laps.removeAll()
    }

    func lap() {
        guard isRunning else { return }
        updateElapsedTime()
        laps.append(StopwatchLap(id: laps.count + 1, splitTime: elapsedTime - lastLapTime))
        lastLapTime = elapsedTime
    }

    static func formattedTime(_ time: TimeInterval) -> String {
        let hundredths = Int(max(0, time) * 100)
        let minutes = hundredths / 6_000
        let seconds = (hundredths / 100) % 60
        let fraction = hundredths % 100
        return String(format: "%02d:%02d.%02d", minutes, seconds, fraction)
    }

    private func updateElapsedTime() {
        guard let startedAt else { return }
        // Measure elapsed time independently of timer delivery to avoid drift.
        elapsedTime = accumulatedTime + ProcessInfo.processInfo.systemUptime - startedAt
    }

    deinit {
        timer?.invalidate()
    }
}

