@MainActor
final class SettingsStore: ObservableObject {
    enum Theme: String, CaseIterable, Identifiable {
        case system, light, dark

        var id: String { rawValue }

        var title: String {
            switch self {
            case .system: return "System"
            case .light: return "Light"
            case .dark: return "Dark"
            }
        }

        var colorScheme: ColorScheme? {
            switch self {
            case .system: return nil
            case .light: return .light
            case .dark: return .dark
            }
        }
    }

    private enum Key {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    @Published var displayName: String {
        didSet { persist(displayName, forKey: Key.displayName, changed: displayName != oldValue) }
    }

    @Published var theme: Theme {
        didSet { persist(theme.rawValue, forKey: Key.theme, changed: theme != oldValue) }
    }

    @Published var notificationsEnabled: Bool {
        didSet {
            persist(notificationsEnabled, forKey: Key.notificationsEnabled,
                    changed: notificationsEnabled != oldValue)
        }
    }

    /// The refresh interval in seconds.
    @Published var refreshInterval: TimeInterval {
        didSet { persist(refreshInterval, forKey: Key.refreshInterval, changed: refreshInterval != oldValue) }
    }

    private let defaults: UserDefaults
    private var defaultsObserver: AnyCancellable?
    private var isReloading = false

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        defaults.register(defaults: [
            Key.displayName: "",
            Key.theme: Theme.system.rawValue,
            Key.notificationsEnabled: true,
            Key.refreshInterval: 300.0
        ])
        displayName = defaults.string(forKey: Key.displayName) ?? ""
        theme = Theme(rawValue: defaults.string(forKey: Key.theme) ?? "") ?? .system
        notificationsEnabled = defaults.bool(forKey: Key.notificationsEnabled)
        refreshInterval = defaults.double(forKey: Key.refreshInterval)

        // Observe all instances: another UserDefaults instance may write to the same suite.
        defaultsObserver = NotificationCenter.default.publisher(for: UserDefaults.didChangeNotification)
            .sink { [weak self] _ in
                Task { @MainActor [weak self] in
                    self?.reload()
                }
            }
        reload()
    }

    private func persist(_ value: Any, forKey key: String, changed: Bool) {
        guard changed, !isReloading else { return }
        defaults.set(value, forKey: key)
    }

    private func reload() {
        isReloading = true
        defer { isReloading = false }

        let name = defaults.string(forKey: Key.displayName) ?? ""
        let choice = Theme(rawValue: defaults.string(forKey: Key.theme) ?? "") ?? .system
        let notifications = defaults.bool(forKey: Key.notificationsEnabled)
        let interval = defaults.double(forKey: Key.refreshInterval)

        if displayName != name { displayName = name }
        if theme != choice { theme = choice }
        if notificationsEnabled != notifications { notificationsEnabled = notifications }
        if refreshInterval != interval { refreshInterval = interval }
    }
}

