            case .dark: return .dark
            }
        }
    }

    enum Key {
        static let displayName = "displayName"
        static let theme = "theme"
        static let notificationsEnabled = "notificationsEnabled"
        static let refreshInterval = "refreshInterval"
    }

    @Published var displayName: String = "" {
        didSet { persist(displayName, forKey: Key.displayName) }
    }

    @Published var theme: Theme = .system {
        didSet { persist(theme.rawValue, forKey: Key.theme) }
    }

    @Published var notificationsEnabled: Bool = true {
        didSet { persist(notificationsEnabled, forKey: Key.notificationsEnabled) }
    }

    /// The refresh interval in seconds.
    @Published var refreshInterval: Double = 60 {
        didSet { persist(refreshInterval, forKey: Key.refreshInterval) }
    }

    private let defaults: UserDefaults
    private var defaultsObserver: AnyCancellable?
    private var isReloading = false

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        // Observe all instances, including other instances of the same suite.
        defaultsObserver = NotificationCenter.default
            .publisher(for: UserDefaults.didChangeNotification)
            .sink { [weak self] _ in
                Task { @MainActor [weak self] in
                    self?.reload()
                }
            }
        reload()
    }

    private func persist(_ value: Any, forKey key: String) {
        guard !isReloading else { return }
        defaults.set(value, forKey: key)
    }

    private func reload() {
        isReloading = true
        defer { isReloading = false }

        let name = defaults.string(forKey: Key.displayName) ?? ""
        let selectedTheme = defaults.string(forKey: Key.theme)
            .flatMap(Theme.init(rawValue:)) ?? .system
        let notifications = defaults.object(forKey: Key.notificationsEnabled) as? Bool ?? true
        let interval = defaults.object(forKey: Key.refreshInterval) as? Double ?? 60

        // Only publish actual changes, and never write back while reloading.
        if displayName != name { displayName = name }
        if theme != selectedTheme { theme = selectedTheme }
        if notificationsEnabled != notifications { notificationsEnabled = notifications }
        if refreshInterval != interval { refreshInterval = interval }
    }
}

