@MainActor
private struct ThumbnailCell: View {
    let url: URL
    @State private var thumbnail: DownloadedThumbnail?
    @State private var failed = false

    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            ZStack {
                Rectangle().fill(.quaternary)
                if let thumbnail {
                    Image(nsImage: thumbnail.image)
                        .resizable()
                        .scaledToFill()
                } else if failed {
                    Image(systemName: "photo.badge.exclamationmark")
                        .accessibilityLabel("Photo could not be downloaded")
                } else {
                    ProgressView()
                        .accessibilityLabel("Downloading photo")
                }
            }
            .frame(height: 140)
            .clipped()
            .clipShape(RoundedRectangle(cornerRadius: 8))

            if let thumbnail {
                TimelineView(.periodic(from: .now, by: 60)) { _ in
                    Text("Downloaded \(thumbnail.downloadedAt, format: .relative(presentation: .named))")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
            } else {
                Text(failed ? "Download failed" : "Loading…")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
