        .task(id: url) {
            thumbnail = nil
            failed = false
            do {
                let downloaded = try await ThumbnailCache.shared.thumbnail(for: url)
                try Task.checkCancellation()
                thumbnail = downloaded
            } catch {
                guard !Task.isCancelled else { return }
                failed = true
            }
        }
    }
}

@MainActor
private final class DownloadedThumbnail: NSObject {
    let image: NSImage
    let downloadedAt: Date

    init(image: NSImage, downloadedAt: Date) {
        self.image = image
        self.downloadedAt = downloadedAt
    }
}

@MainActor
private final class ThumbnailCache {
    static let shared = ThumbnailCache()

    private let images = NSCache<NSURL, DownloadedThumbnail>()
    private var downloads: [URL: Task<DownloadedThumbnail, Error>] = [:]

    private init() {
        images.countLimit = 300
    }

    func thumbnail(for url: URL) async throws -> DownloadedThumbnail {
        if let cached = images.object(forKey: url as NSURL) {
            return cached
        }
        if let download = downloads[url] {
            return try await download.value
        }

        // A shared download outlives an individual cell's scrolling lifecycle.
        let download = Task { @MainActor in
            defer { downloads[url] = nil }
            let (data, response) = try await URLSession.shared.data(from: url)
            if let response = response as? HTTPURLResponse,
               !(200..<300).contains(response.statusCode) {
                throw URLError(.badServerResponse)
            }
            guard let image = NSImage(data: data) else {
                throw URLError(.cannotDecodeContentData)
            }
            let thumbnail = DownloadedThumbnail(image: image, downloadedAt: .now)
            images.setObject(thumbnail, forKey: url as NSURL)
            return thumbnail
        }
        downloads[url] = download
        return try await download.value
    }
}

