/// Main-actor isolation keeps AppKit images and cache mutations synchronized.
@MainActor
private final class ThumbnailCache {
    struct Entry {
        let image: NSImage
        let downloadedAt: Date
    }

    static let shared = ThumbnailCache()

    private var entries: [URL: Entry] = [:]
    private var downloads: [URL: Task<Entry, Error>] = [:]

    func thumbnail(for url: URL) async throws -> Entry {
        if let entry = entries[url] { return entry }
        if let download = downloads[url] { return try await download.value }

        // A disappearing cell must not cancel a download shared by other cells.
        let download = Task { @MainActor in
            let (data, response) = try await URLSession.shared.data(from: url)
            if let response = response as? HTTPURLResponse,
               !(200..<300).contains(response.statusCode) {
                throw URLError(.badServerResponse)
            }
            guard let image = NSImage(data: data) else {
                throw URLError(.cannotDecodeContentData)
            }
            return Entry(image: image, downloadedAt: Date())
        }
        downloads[url] = download
        defer { downloads[url] = nil }

        let entry = try await download.value
        entries[url] = entry
        return entry
    }
}

