/// A stand-in for the SDK; returns sample coordinates without a network request.
final class LegacyGeocoder {
    func geocode(
        _ address: String,
        completion: @escaping (Result<(Double, Double), Error>) -> Void
    ) {
        completion(.success((0, 0)))
    }
}

/// A stand-in for the SDK; simulates progress without transferring a file.
final class LegacyUploader {
    var onProgress: ((Double) -> Void)?
    var onFinish: ((Error?) -> Void)?

    func start(file: URL) {
        onProgress?(0)
        onProgress?(0.5)
        onProgress?(1)
        onFinish?(nil)
    }
}

extension LegacyGeocoder {
    /// Bridges the SDK's single completion callback into an async result.
    func geocode(_ address: String) async throws -> (Double, Double) {
        try Task.checkCancellation()
        let coordinates: (Double, Double) = try await withCheckedThrowingContinuation {
            continuation in
            geocode(address) { result in
                continuation.resume(with: result)
            }
        }
        try Task.checkCancellation()
        return coordinates
    }
}

/// Owns one upload. Consume `progress` concurrently with `upload(file:)`.
/// The SDK has no cancellation API, so cancellation during an upload is observed
/// after its completion callback arrives. Upload failures are thrown by `upload`.
actor UploadBridge {
    enum UploadError: Error {
        case alreadyStarted
    }

    nonisolated let progress: AsyncStream<Double>

    private let progressContinuation: AsyncStream<Double>.Continuation
    private let uploader = LegacyUploader()
    private var hasStarted = false

    init() {
        let stream = AsyncStream<Double>.makeStream()
        progress = stream.stream
        progressContinuation = stream.continuation
    }

    func upload(file: URL) async throws {
        guard !hasStarted else { throw UploadError.alreadyStarted }
        hasStarted = true

        defer {
            uploader.onProgress = nil
            uploader.onFinish = nil
            progressContinuation.finish()
        }

        try Task.checkCancellation()
        let progressContinuation = self.progressContinuation
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            uploader.onProgress = { value in
                progressContinuation.yield(value)
            }
            uploader.onFinish = { error in
                progressContinuation.finish()
                if let error {
                    continuation.resume(throwing: error)
                } else {
                    continuation.resume(returning: ())
                }
            }
            uploader.start(file: file)
        }
        try Task.checkCancellation()
    }
}

