/// One upload and its progress stream. Create a new instance for each file.
actor AsyncUploader {
    enum UploadError: Error {
        case alreadyStarted
    }

    /// Consume concurrently with `upload(file:)`. Completion errors come from that method.
    nonisolated let progress: AsyncStream<Double>

    private let uploader = LegacyUploader()
    private let progressContinuation: AsyncStream<Double>.Continuation
    private var hasStarted = false

    init() {
        let stream = AsyncStream<Double>.makeStream()
        progress = stream.stream
        progressContinuation = stream.continuation
    }

    deinit {
        progressContinuation.finish()
    }

    /// The SDK has no cancellation API, so cancellation during an upload is
    /// observed after its finish callback. Progress ends on success or failure.
    func upload(file: URL) async throws {
        guard !hasStarted else { throw UploadError.alreadyStarted }
        hasStarted = true

        defer {
            uploader.onProgress = nil
            uploader.onFinish = nil
            progressContinuation.finish()
        }

        try Task.checkCancellation()
        let progressContinuation = progressContinuation
        try await withCheckedThrowingContinuation {
            (continuation: CheckedContinuation<Void, Error>) in
            uploader.onProgress = { value in
                progressContinuation.yield(value)
            }
            uploader.onFinish = { error in
                progressContinuation.finish()
                if let error {
                    continuation.resume(throwing: error)
                } else {
                    continuation.resume()
                }
            }
            uploader.start(file: file)
        }
        try Task.checkCancellation()
    }
}

import Foundation
import SwiftUI

private struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
private final class ChatModel: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []
    @Published private(set) var isConnected = false
    @Published private(set) var isSending = false
    @Published private(set) var status = "Connecting…"
    @Published private(set) var errorMessage: String?
    @Published var draft = ""

    private var socket: URLSessionWebSocketTask?
    private var connectionID: UUID?

    func connect() async {
        let connectionID = UUID()
        self.connectionID = connectionID
        socket?.cancel(with: .goingAway, reason: nil)
        var retryDelay: UInt64 = 1

        defer {
            if self.connectionID == connectionID {
                socket?.cancel(with: .goingAway, reason: nil)
                socket = nil
                isConnected = false
                status = "Disconnected"
                self.connectionID = nil
            }
        }

        while !Task.isCancelled, self.connectionID == connectionID {
            guard let url = URL(string: "wss://chat.example.com/room") else { return }
            let socket = URLSession.shared.webSocketTask(with: url)
            self.socket = socket
            isConnected = false
            status = "Connecting…"
            socket.resume()

            do {
                try await withTaskCancellationHandler {
                    // A successful ping confirms the WebSocket handshake has completed.
                    try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                        socket.sendPing { error in
                            if let error {
                                continuation.resume(throwing: error)
                            } else {
                                continuation.resume()
                            }
                        }
                    }
                    try Task.checkCancellation()
                    guard self.connectionID == connectionID else { return }
                    isConnected = true
                    status = "Connected"

                    while !Task.isCancelled, self.connectionID == connectionID {
                        let frame = try await socket.receive()
                        try Task.checkCancellation()
                        guard self.connectionID == connectionID else { return }
                        retryDelay = 1
                        let data: Data
                        switch frame {
                        case .string(let text): data = Data(text.utf8)
                        case .data(let bytes): data = bytes
                        @unknown default: continue
                        }
                        do {
                            let message = try JSONDecoder().decode(ChatMessage.self, from: data)
                            append(message)
                        } catch {
                            errorMessage = "Received a message in an unsupported format."
                        }
                    }
                } onCancel: {
                    socket.cancel(with: .goingAway, reason: nil)
                }
            } catch {
                guard !Task.isCancelled, self.connectionID == connectionID else { return }
            }

            socket.cancel(with: .goingAway, reason: nil)
            guard !Task.isCancelled, self.connectionID == connectionID else { return }
            self.socket = nil
            isConnected = false
            status = "Connection lost. Reconnecting in \(retryDelay)s…"
            do {
                try await Task.sleep(nanoseconds: retryDelay * 1_000_000_000)
            } catch {
                return
            }
            retryDelay = min(retryDelay * 2, 30)
        }
    }

    func send(author: String) async {
        let text = draft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty, isConnected, !isSending, let socket else { return }
        let originalDraft = draft
        let message = ChatMessage(id: UUID().uuidString, author: author, text: text)
        isSending = true
        errorMessage = nil
        defer { isSending = false }

        do {
            let data = try JSONEncoder().encode(message)
            try await socket.send(.string(String(decoding: data, as: UTF8.self)))
            guard self.socket === socket else { return }
            append(message)
            if draft == originalDraft { draft = "" }
        } catch {
            guard self.socket === socket else { return }
            errorMessage = "Could not send your message. Your draft is saved; try again after reconnecting."
            isConnected = false
            // Cancelling also releases receive(), so the single connection loop retries.
            socket.cancel(with: .goingAway, reason: nil)
        }
    }

    private func append(_ message: ChatMessage) {
        if let index = messages.firstIndex(where: { $0.id == message.id }) {
            messages[index] = message
        } else {
            messages.append(message)
        }
    }
}

