import { useEffect, useId, useMemo, useState } from "react";

export interface User {
  id: string | number;
  name: string;
  email: string;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  return (
    "id" in value &&
    (typeof value.id === "string" || typeof value.id === "number") &&
    "name" in value &&
    typeof value.name === "string" &&
    "email" in value &&
    typeof value.email === "string"
  );
}

/** Expects /api/users to return a JSON array of users. */
export default function UserSearch() {
  const searchId = useId();
  const sortId = useId();
  const [query, setQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [sortBy, setSortBy] = useState<"name" | "email">("name");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const term = query.trim();

  useEffect(() => {
    const controller = new AbortController();
    let active = true;
    setUsers([]);
    setError(null);
    setLoading(term.length > 0);

    if (!term) return;

    const timeout = setTimeout(async () => {
      try {
        const response = await fetch(`/api/users?q=${encodeURIComponent(term)}`, {
          signal: controller.signal,
        });
        if (!response.ok) {
          throw new Error(`User search failed (${response.status}). Please try again.`);
        }
        const data: unknown = await response.json();
        if (!Array.isArray(data) || !data.every(isUser)) {
          throw new Error("The server returned an invalid user list.");
        }
        if (active) setUsers(data);
      } catch (cause: unknown) {
        if (active) {
          setError(cause instanceof Error ? cause.message : "Unable to search users. Please try again.");
        }
      } finally {
        if (active) setLoading(false);
      }
    }, 300);

    return () => {
      active = false;
      clearTimeout(timeout);
      controller.abort();
    };
  }, [term]);

  const sortedUsers = useMemo(
    () => [...users].sort((a, b) => a[sortBy].localeCompare(b[sortBy])),
    [users, sortBy],
  );

  return (
    <section aria-label="User search">
      <label htmlFor={searchId}>Search users</label>
      <input
        id={searchId}
        type="search"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        placeholder="Enter a search term"
      />

      <label htmlFor={sortId}>Sort results by</label>
      <select
        id={sortId}
        value={sortBy}
        onChange={(event) => setSortBy(event.target.value === "email" ? "email" : "name")}
      >
        <option value="name">Name</option>
        <option value="email">Email</option>
      </select>

      <p role="status">
        {loading
          ? "Loading users…"
          : error
            ? "Search unsuccessful."
            : !term
              ? "Enter a search term to find users."
              : `${users.length} ${users.length === 1 ? "result" : "results"}`}
      </p>
      {error && <p role="alert">{error}</p>}
      {!loading && !error && term && users.length === 0 && <p>No matching users.</p>}
      <ul aria-label="Matching users" aria-busy={loading}>
        {sortedUsers.map((user) => (
          <li key={user.id}>
            <strong>{user.name}</strong> — {user.email} (ID: {user.id})
          </li>
        ))}
      </ul>
    </section>
  );
}

