private struct ChatContentHeight: PreferenceKey {
    static let defaultValue: CGFloat = 0

    static func reduce(value: inout CGFloat, nextValue: () -> CGFloat) {
        value = nextValue()
    }
}

private struct ChatMessage: Codable, Identifiable {
    let id: String
    let author: String
    let text: String
}

@MainActor
private final class ChatConnection: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []
    @Published private(set) var status = "Disconnected"
    @Published private(set) var isConnected = false
    @Published private(set) var isSending = false
    @Published private(set) var error: String?

    private var socket: URLSessionWebSocketTask?
    private var runID: UUID?
    private let maximumRetryDelay: UInt64 = 30
    private let nanosecondsPerSecond: UInt64 = 1_000_000_000

    func run() async {
        let id = UUID()
        runID = id
        socket?.cancel(with: .goingAway, reason: nil)
        let session = URLSession(configuration: .default)
        defer {
            session.invalidateAndCancel()
            if runID == id {
                socket = nil
                isConnected = false
                status = "Disconnected"
            }
        }

        guard let url = URL(string: "wss://chat.example.com/room") else { return }
        var retryDelay: UInt64 = 1
        while !Task.isCancelled && runID == id {
            let connection = session.webSocketTask(with: url)
            socket = connection
            isConnected = false
            status = "Connecting…"
            connection.resume()

            do {
                try await withTaskCancellationHandler {
                    try await withCheckedThrowingContinuation {
                        (continuation: CheckedContinuation<Void, Error>) in
                        connection.sendPing { error in
                            if let error {
                                continuation.resume(throwing: error)
                            } else {
                                continuation.resume()
                            }
                        }
                    }
                    try Task.checkCancellation()
                    guard runID == id else { return }
                    isConnected = true
                    status = "Connected"
                    error = nil
                    while !Task.isCancelled && runID == id {
                        let frame = try await connection.receive()
                        try Task.checkCancellation()
                        guard runID == id else { return }
                        retryDelay = 1
                        let data: Data
                        switch frame {
                        case .string(let text): data = Data(text.utf8)
                        case .data(let bytes): data = bytes
                        @unknown default: continue
                        }
                        do {
                            append(try JSONDecoder().decode(ChatMessage.self, from: data))
                        } catch {
                            self.error = "Received a message in an unsupported format."
                        }
                    }
                } onCancel: {
                    connection.cancel(with: .goingAway, reason: nil)
                }
            } catch {
                if !Task.isCancelled && runID == id {
                    self.error = "Connection failed: \(error.localizedDescription)"
                }
            }

            connection.cancel(with: .goingAway, reason: nil)
            guard !Task.isCancelled && runID == id else { return }
            isConnected = false
            status = "Connection lost. Retrying in \(retryDelay)s…"
            do {
                try await Task.sleep(nanoseconds: retryDelay * nanosecondsPerSecond)
            } catch {
                return
            }
            retryDelay = min(retryDelay * 2, maximumRetryDelay)
        }
    }

    func send(text: String, author: String) async -> Bool {
        guard isConnected, !isSending, let connection = socket else { return false }
        isSending = true
        defer { isSending = false }
        let message = ChatMessage(id: UUID().uuidString, author: author, text: text)
        do {
            let data = try JSONEncoder().encode(message)
            try await connection.send(.string(String(decoding: data, as: UTF8.self)))
            guard socket === connection, !Task.isCancelled else { return false }
            append(message)
            error = nil
            return true
        } catch {
            if socket === connection {
                self.error = "Message could not be sent. Your draft has been kept."
                isConnected = false
                connection.cancel(with: .goingAway, reason: nil)
            }
            return false
        }
    }

    private func append(_ message: ChatMessage) {
        // A server echo or replay must not duplicate an existing row.
        guard !messages.contains(where: { $0.id == message.id }) else { return }
        messages.append(message)
    }
}

import { useEffect, useId, useMemo, useState } from "react";

const SEARCH_DEBOUNCE_MS = 300;

export interface User {
  id: string | number;
  name: string;
  email: string;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  return (
    "id" in value &&
    (typeof value.id === "string" || typeof value.id === "number") &&
    "name" in value &&
    typeof value.name === "string" &&
    "email" in value &&
    typeof value.email === "string"
  );
}

export function UserSearch() {
  const searchId = useId();
  const sortId = useId();
  const [query, setQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [sortBy, setSortBy] = useState<"name" | "email">("name");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const term = query.trim();

  useEffect(() => {
    const controller = new AbortController();
    setUsers([]);
    setError(null);
    setLoading(Boolean(term));

    if (!term) return;

    const timeout = setTimeout(async () => {
      try {
        const response = await fetch(`/api/users?q=${encodeURIComponent(term)}`, {
          signal: controller.signal,
        });
        if (!response.ok) {
          throw new Error(`Unable to load users (HTTP ${response.status}).`);
        }

        const userData: unknown = await response.json();
        if (!Array.isArray(userData) || !userData.every(isUser)) {
          throw new Error("The server returned an invalid user list.");
        }
        if (!controller.signal.aborted) setUsers(userData);
      } catch (cause: unknown) {
        if (!controller.signal.aborted) {
          setError(cause instanceof Error ? cause.message : "Unable to load users.");
        }
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    }, SEARCH_DEBOUNCE_MS);

    return () => {
      clearTimeout(timeout);
      controller.abort();
    };
  }, [term]);

  const sortedUsers = useMemo(
    () => [...users].sort((a, b) => a[sortBy].localeCompare(b[sortBy])),
    [users, sortBy],
  );

  return (
    <section aria-label="User search">
