          ? "Loading users…"
          : `${users.length} ${users.length === 1 ? "result" : "results"}`}
      </p>
      {error && <p role="alert">{error}</p>}
      {!term && <p>Type to search for users.</p>}
      {term && !loading && !error && users.length === 0 && (
        <p>No matching users found.</p>
      )}
      {sortedUsers.length > 0 && (
        <table>
          <caption>Matching users</caption>
          <thead>
