import { useEffect, useState } from "react";

export interface Metric {
  name: string;
  value: number;
  unit: string;
}

interface Snapshot {
  metrics: Metric[];
  changed: Set<string>;
  updatedAt: number | null;
}

function isMetrics(data: unknown): data is Metric[] {
  return Array.isArray(data) && data.every((metric: unknown) => {
    if (typeof metric !== "object" || metric === null) return false;
    return "name" in metric && typeof metric.name === "string"
      && "value" in metric && typeof metric.value === "number"
      && Number.isFinite(metric.value)
      && "unit" in metric && typeof metric.unit === "string";
  });
}

export function MetricsPanel() {
  const [snapshot, setSnapshot] = useState<Snapshot>({
    metrics: [], changed: new Set(), updatedAt: null,
  });
  const [error, setError] = useState<string | null>(null);
  const [now, setNow] = useState(Date.now);

  useEffect(() => {
    let disposed = false;
    let request: AbortController | null = null;
    let pollTimer: ReturnType<typeof setInterval> | undefined;
    let clockTimer: ReturnType<typeof setInterval> | undefined;

    async function refresh() {
      if (disposed || document.hidden || request) return;
      const controller = new AbortController();
      request = controller;
      try {
        const response = await fetch("/api/metrics", {
          signal: controller.signal,
          cache: "no-store",
        });
        if (!response.ok) throw new Error(`Request failed (${response.status})`);
        const metrics: unknown = await response.json();
        if (!isMetrics(metrics)) throw new Error("Invalid metrics response");
        if (disposed || controller.signal.aborted) return;

        const updatedAt = Date.now();
        setSnapshot((previous) => {
          const values = new Map(previous.metrics.map((metric) => [metric.name, metric.value]));
          return {
            metrics,
            changed: new Set(metrics
              .filter((metric) => values.has(metric.name) && values.get(metric.name) !== metric.value)
              .map((metric) => metric.name)),
            updatedAt,
          };
        });
        setNow(updatedAt);
        setError(null);
      } catch (cause) {
        if (!disposed && !controller.signal.aborted) {
          setError(cause instanceof Error ? cause.message : "Unable to load metrics");
        }
      } finally {
        if (request === controller) request = null;
      }
    }

    function stop() {
      clearInterval(pollTimer);
      clearInterval(clockTimer);
      request?.abort();
      request = null;
    }

    function syncVisibility() {
      stop();
      if (document.hidden) return;
      setNow(Date.now());
      void refresh();
      pollTimer = setInterval(() => void refresh(), 10_000);
      clockTimer = setInterval(() => setNow(Date.now()), 1_000);
    }

    document.addEventListener("visibilitychange", syncVisibility);
    syncVisibility();
    return () => {
      disposed = true;
      document.removeEventListener("visibilitychange", syncVisibility);
      stop();
    };
  }, []);

  const secondsAgo = snapshot.updatedAt === null
    ? null
    : Math.max(0, Math.floor((now - snapshot.updatedAt) / 1_000));

  return (
    <section aria-label="Metrics" style={{ padding: 24, border: "1px solid #cbd5e1", borderRadius: 12 }}>
      <h2>Metrics</h2>
      <p>{secondsAgo === null
        ? (error ? "No metrics loaded yet" : "Loading metrics…")
        : `Last updated ${secondsAgo} ${secondsAgo === 1 ? "second" : "seconds"} ago`}</p>
      {error && <p role="alert">Unable to refresh metrics: {error}</p>}
      {snapshot.updatedAt !== null && snapshot.metrics.length === 0 && <p>No metrics available.</p>}
      <dl style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 12 }}>
        {snapshot.metrics.map((metric) => {
          const changed = snapshot.changed.has(metric.name);
          return (
            <div key={metric.name} data-changed={changed} style={{
              padding: 16,
              borderRadius: 8,
              border: `2px solid ${changed ? "#a16207" : "#cbd5e1"}`,
              backgroundColor: changed ? "#fef9c3" : "#f8fafc",
              color: "#0f172a",
            }}>
              <dt>{metric.name}</dt>
              <dd style={{ margin: "8px 0 0", fontSize: 24, fontWeight: 600 }}>
                {metric.value} {metric.unit}
              </dd>
              {changed && <span style={{ fontSize: 12 }}>Changed since last refresh</span>}
            </div>
          );
        })}
      </dl>
    </section>
  );
}

export default MetricsPanel;

import { useEffect, useState } from "react";

type Metric = { name: string; value: number; unit: string };

type Snapshot = {
  metrics: Metric[];
  changed: Set<string>;
  updatedAt: number | null;
};

const REFRESH_INTERVAL_MS = 10_000;

function isMetrics(data: unknown): data is Metric[] {
  return Array.isArray(data) && data.every((metric: unknown) => {
    if (typeof metric !== "object" || metric === null) return false;
    return "name" in metric && typeof metric.name === "string"
      && "value" in metric && typeof metric.value === "number"
      && Number.isFinite(metric.value)
      && "unit" in metric && typeof metric.unit === "string";
  });
}

export function MetricsPanel() {
  const [snapshot, setSnapshot] = useState<Snapshot>({
    metrics: [], changed: new Set(), updatedAt: null,
  });
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [now, setNow] = useState(() => Date.now());

  useEffect(() => {
    let disposed = false;
    let request: AbortController | null = null;
    let poll: ReturnType<typeof setInterval> | undefined;
    // Keep the previous successful response, independent of render timing.
    let previous = new Map<string, number>();

    async function refresh() {
      if (disposed || request) return;
      const controller = new AbortController();
      request = controller;
      try {
        const response = await fetch("/api/metrics", {
          signal: controller.signal,
          cache: "no-store",
        });
        if (!response.ok) throw new Error(`Metrics request failed (${response.status}).`);
        const metrics: unknown = await response.json();
        if (!isMetrics(metrics)) throw new Error("The metrics response has an invalid format.");
        if (disposed) return;

        const changed = new Set(metrics
          .filter((metric) => previous.has(metric.name)
            && previous.get(metric.name) !== metric.value)
          .map((metric) => metric.name));
        previous = new Map(metrics.map((metric) => [metric.name, metric.value]));
        const updatedAt = Date.now();
        setSnapshot({ metrics, changed, updatedAt });
        setNow(updatedAt);
        setError(null);
      } catch (cause) {
        if (!disposed && !controller.signal.aborted) {
          setError(cause instanceof Error ? cause.message : "Unable to load metrics.");
        }
      } finally {
        request = null;
        if (!disposed) setLoading(false);
      }
    }

    function updatePolling() {
      clearInterval(poll);
      poll = undefined;
      if (!document.hidden) {
        void refresh();
        poll = setInterval(() => {
          if (!document.hidden) void refresh();
        }, REFRESH_INTERVAL_MS);
      }
    }

    // Always load on mount; subsequent requests only run while visible.
    void refresh();
    updatePolling();
    document.addEventListener("visibilitychange", updatePolling);
    const clock = setInterval(() => setNow(Date.now()), 1_000);

    return () => {
      disposed = true;
      clearInterval(poll);
      clearInterval(clock);
      document.removeEventListener("visibilitychange", updatePolling);
      request?.abort();
    };
  }, []);

  const secondsAgo = snapshot.updatedAt === null
    ? null
    : Math.max(0, Math.floor((now - snapshot.updatedAt) / 1_000));

  return (
    <section aria-label="Metrics dashboard">
      <h2>Metrics</h2>
      <p>{secondsAgo === null ? "Not updated yet" : `last updated ${secondsAgo} seconds ago`}</p>
      {loading && <p role="status">Loading metrics…</p>}
      {error && <p role="alert">{error}</p>}
      {snapshot.updatedAt !== null && snapshot.metrics.length === 0 && <p>No metrics available.</p>}
      {snapshot.metrics.length > 0 && (
        <table>
          <thead>
            <tr><th scope="col">Metric</th><th scope="col">Value</th><th scope="col">Change</th></tr>
          </thead>
          <tbody>
            {snapshot.metrics.map((metric) => {
              const changed = snapshot.changed.has(metric.name);
              return (
                <tr key={metric.name} style={changed ? { backgroundColor: "#fef3c7", color: "#78350f" } : undefined}>
                  <th scope="row">{metric.name}</th>
                  <td>{metric.value} {metric.unit}</td>
                  <td>{changed ? "Changed" : "—"}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </section>
  );
}

