type Values = {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
};
type Field = keyof Values;
type Errors = Partial<Record<Field, string>>;

const emptyValues: Values = {
  name: '',
  email: '',
  password: '',
  confirmPassword: '',
  acceptTerms: false,
};

const textFields = [
  { field: 'name', label: 'Name', type: 'text', autoComplete: 'name' },
  { field: 'email', label: 'Email', type: 'email', autoComplete: 'email' },
  { field: 'password', label: 'Password', type: 'password', autoComplete: 'new-password' },
  { field: 'confirmPassword', label: 'Confirm password', type: 'password', autoComplete: 'new-password' },
] as const;

function validate(values: Values): Errors {
  const errors: Errors = {};
  if (!values.name.trim()) errors.name = 'Enter your name.';
  if (!values.email.trim()) errors.email = 'Enter your email address.';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) {
    errors.email = 'Enter a valid email address.';
  }
  if (!values.password) errors.password = 'Enter a password.';
  if (!values.confirmPassword) errors.confirmPassword = 'Confirm your password.';
  else if (values.password !== values.confirmPassword) {
    errors.confirmPassword = 'Passwords must match.';
  }
  if (!values.acceptTerms) errors.acceptTerms = 'Accept the terms to continue.';
  return errors;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function SignupForm() {
  const prefix = useId();
  const [values, setValues] = useState<Values>(emptyValues);
  const [errors, setErrors] = useState<Errors>({});
  const [formError, setFormError] = useState('');
  const [success, setSuccess] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const submitting = useRef(false);

  function update<K extends Field>(field: K, value: Values[K]) {
    setValues(previous => ({ ...previous, [field]: value }));
    setErrors(previous => ({
      ...previous,
      [field]: undefined,
      ...(field === 'password' ? { confirmPassword: undefined } : {}),
    }));
    setFormError('');
    setSuccess('');
  }

  function validateField(field: Field) {
    const message = validate(values)[field];
    setErrors(previous => ({ ...previous, [field]: message }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submitting.current) return;
    setSuccess('');
    setFormError('');
    const validationErrors = validate(values);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) return;

    submitting.current = true;
    setIsSubmitting(true);
    try {
      const response = await fetch('/api/signup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...values, name: values.name.trim(), email: values.email.trim() }),
      });
      const data: unknown = await response.json();
      if (isRecord(data) && isRecord(data.errors)) {
        const serverErrors: Errors = {};
        const otherErrors: string[] = [];
        for (const [field, message] of Object.entries(data.errors)) {
          if (typeof message !== 'string' || !message) continue;
          if (Object.prototype.hasOwnProperty.call(emptyValues, field)) {
            serverErrors[field as Field] = message;
          } else {
            otherErrors.push(message);
          }
        }
        if (Object.keys(serverErrors).length || otherErrors.length) {
          setErrors(serverErrors);
          setFormError(otherErrors.join(' '));
          return;
        }
      }
      if (!response.ok) {
        setFormError('Unable to create your account. Please try again.');
        return;
      }
      if (!isRecord(data) || !(
        (typeof data.id === 'string' && data.id.trim() !== '') ||
        (typeof data.id === 'number' && Number.isFinite(data.id))
      )) {
        setFormError('The server did not return an account ID. Your account may have been created.');
        return;
      }
      setSuccess(`Account created successfully! Your account ID is ${data.id}.`);
      setValues({ ...emptyValues });
      setErrors({});
    } catch {
      setFormError('Unable to confirm account creation. Please check your connection and try again.');
    } finally {
      submitting.current = false;
      setIsSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate aria-busy={isSubmitting}>
      <h2>Create an account</h2>
      {textFields.map(({ field, label, type, autoComplete }) => (
        <div key={field}>
          <label htmlFor={`${prefix}-${field}`}>{label}</label>
          <input
            id={`${prefix}-${field}`}
            name={field}
            type={type}
            autoComplete={autoComplete}
            required
            disabled={isSubmitting}
            value={values[field]}
            onChange={event => update(field, event.target.value)}
            onBlur={() => validateField(field)}
            aria-invalid={Boolean(errors[field])}
            aria-describedby={errors[field] ? `${prefix}-${field}-error` : undefined}
          />
          {errors[field] && <p id={`${prefix}-${field}-error`} role="alert">{errors[field]}</p>}
        </div>
      ))}
      <div>
        <label htmlFor={`${prefix}-acceptTerms`}>
          <input
            id={`${prefix}-acceptTerms`}
            name="acceptTerms"
            type="checkbox"
            required
            disabled={isSubmitting}
            checked={values.acceptTerms}
            onChange={event => update('acceptTerms', event.target.checked)}
            onBlur={() => validateField('acceptTerms')}
            aria-invalid={Boolean(errors.acceptTerms)}
            aria-describedby={errors.acceptTerms ? `${prefix}-acceptTerms-error` : undefined}
          />
          I accept the terms
        </label>
        {errors.acceptTerms && <p id={`${prefix}-acceptTerms-error`} role="alert">{errors.acceptTerms}</p>}
      </div>
      {formError && <p role="alert">{formError}</p>}
      <p role="status">{success}</p>
      <button type="submit" disabled={isSubmitting}>
        {isSubmitting ? 'Creating account…' : 'Sign up'}
      </button>
    </form>
  );
}

