import { useEffect, useRef, useState, type FormEvent } from 'react';

export interface ChatRoomProps {
  roomId: string;
}

interface Message {
  id: string;
  author: string;
  text: string;
  sentAt: string | number;
}

type Status = 'connecting' | 'connected' | 'reconnecting';

function isMessage(value: unknown): value is Message {
  if (typeof value !== 'object' || value === null) return false;
  const message = value as Record<string, unknown>;
  return (
    typeof message.id === 'string' &&
    typeof message.author === 'string' &&
    typeof message.text === 'string' &&
    (typeof message.sentAt === 'string' ||
      (typeof message.sentAt === 'number' && Number.isFinite(message.sentAt)))
  );
}

export function ChatRoom({ roomId }: ChatRoomProps) {
  const [room, setRoom] = useState<{
    id: string;
    messages: Message[];
    status: Status;
  }>({ id: roomId, messages: [], status: 'connecting' });
  const [draft, setDraft] = useState({ roomId, text: '' });
  const [sendError, setSendError] = useState('');
  const connection = useRef<{ roomId: string; socket: WebSocket } | null>(null);
  const messageList = useRef<HTMLUListElement>(null);

  useEffect(() => {
    let disposed = false;
    let socket: WebSocket | null = null;
    let retryTimer: ReturnType<typeof setTimeout> | undefined;
    let attempts = 0;

    setRoom({ id: roomId, messages: [], status: 'connecting' });
    setDraft({ roomId, text: '' });
    setSendError('');

    function reconnect() {
      if (disposed || retryTimer !== undefined) return;
      setRoom((current) => ({ ...current, status: 'reconnecting' }));
      const delay = Math.min(1000 * 2 ** attempts, 30_000);
      attempts = Math.min(attempts + 1, 5);
      retryTimer = setTimeout(() => {
        retryTimer = undefined;
        connect();
      }, delay);
    }

    function connect() {
      if (disposed) return;
      let next: WebSocket;
      try {
        next = new WebSocket(
          `wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`,
        );
      } catch {
        reconnect();
        return;
      }
      socket = next;
      connection.current = { roomId, socket: next };
      const isCurrent = () => !disposed && socket === next;

      next.onopen = () => {
        if (!isCurrent()) return;
        attempts = 0;
        setRoom((current) => ({ ...current, status: 'connected' }));
        setSendError('');
      };
      next.onmessage = (event: MessageEvent) => {
        if (!isCurrent() || typeof event.data !== 'string') return;
        let message: unknown;
        try {
          message = JSON.parse(event.data);
        } catch {
          return;
        }
        if (!isMessage(message)) return;
        const incoming = message;
        setRoom((current) => {
          if (current.messages.some((item) => item.id === incoming.id)) return current;
          return { ...current, messages: [...current.messages, incoming] };
        });
      };
      next.onerror = () => {
        if (!isCurrent()) return;
        setRoom((current) => ({ ...current, status: 'reconnecting' }));
        // Closing ensures errors follow the same retry path as disconnects.
        next.close();
      };
      next.onclose = () => {
        if (!isCurrent()) return;
        connection.current = null;
        reconnect();
      };
    }

    connect();
    return () => {
      disposed = true;
      clearTimeout(retryTimer);
      if (connection.current?.socket === socket) connection.current = null;
      if (socket) {
        socket.onopen = null;
        socket.onmessage = null;
        socket.onerror = null;
        socket.onclose = null;
        socket.close();
      }
    };
  }, [roomId]);

  useEffect(() => {
    const list = messageList.current;
    if (list) list.scrollTop = list.scrollHeight;
  }, [room.messages, roomId]);

  const isCurrentRoom = room.id === roomId;
  const status = isCurrentRoom ? room.status : 'connecting';
  const text = draft.roomId === roomId ? draft.text : '';

  function sendMessage(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const active = connection.current;
    if (!text.trim()) return;
    if (
      active?.roomId !== roomId ||
      active.socket.readyState !== WebSocket.OPEN
    ) {
      setSendError('Wait for the connection before sending.');
      return;
    }
    try {
      // The server supplies the message ID, author, and timestamp, then echoes it.
      active.socket.send(JSON.stringify({ text: text.trim() }));
      setDraft({ roomId, text: '' });
      setSendError('');
    } catch {
      setSendError('Message could not be sent. Please try again.');
    }
  }

  return (
    <section aria-label={`Chat room ${roomId}`}>
      <h2>Room {roomId}</h2>
      <div role="status" aria-live="polite">
        {status === 'reconnecting'
          ? 'Reconnecting…'
          : status === 'connecting'
            ? 'Connecting…'
            : 'Connected'}
      </div>
      <ul
        ref={messageList}
        role="log"
        aria-label="Messages"
        aria-live="polite"
        tabIndex={0}
        style={{ maxHeight: '24rem', overflowY: 'auto' }}
      >
        {isCurrentRoom && room.messages.map((message) => (
          <li key={message.id}>
            <strong>{message.author}</strong>{' '}
            <span>{String(message.sentAt)}</span>
            <p style={{ whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }}>
              {message.text}
            </p>
          </li>
        ))}
      </ul>
      <form onSubmit={sendMessage}>
        <label>
          Message
          <input
            value={text}
            onChange={(event) => setDraft({ roomId, text: event.target.value })}
            autoComplete="off"
          />
        </label>
        <button type="submit" disabled={status !== 'connected' || !text.trim()}>
          Send
        </button>
        {sendError && <p role="alert">{sendError}</p>}
      </form>
    </section>
  );
}

export default ChatRoom;

import { useEffect, useRef, useState, type FormEvent } from 'react';

const INITIAL_RETRY_DELAY_MS = 1_000;
const MAX_RETRY_DELAY_MS = 30_000;

export interface ChatRoomProps {
  roomId: string;
}

interface Message {
  id: string;
  author: string;
  text: string;
  sentAt: string | number;
}

function isMessage(value: unknown): value is Message {
  if (typeof value !== 'object' || value === null) return false;
  const message = value as Record<string, unknown>;
  return (
    typeof message.id === 'string' &&
    typeof message.author === 'string' &&
    typeof message.text === 'string' &&
    (typeof message.sentAt === 'string' ||
      (typeof message.sentAt === 'number' && Number.isFinite(message.sentAt)))
  );
}

function parseMessage(data: string): Message | null {
  try {
    const value: unknown = JSON.parse(data);
    return isMessage(value) ? value : null;
  } catch {
    return null;
  }
}

// A room change starts a fresh session, including its messages and draft.
export function ChatRoom({ roomId }: ChatRoomProps) {
  return <RoomSession key={roomId} roomId={roomId} />;
}

function RoomSession({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [draft, setDraft] = useState('');
  const [status, setStatus] = useState<'connecting' | 'connected' | 'reconnecting'>(
    'connecting',
  );
  const [sendError, setSendError] = useState('');
  const socketRef = useRef<WebSocket | null>(null);
  const endRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    let disposed = false;
    let retryTimer: ReturnType<typeof setTimeout> | undefined;
    let retryDelay = INITIAL_RETRY_DELAY_MS;
    let activeSocket: WebSocket | null = null;

    function scheduleReconnect() {
      if (disposed || retryTimer !== undefined) return;
      setStatus('reconnecting');
      retryTimer = setTimeout(() => {
        retryTimer = undefined;
        connect();
      }, retryDelay);
      retryDelay = Math.min(retryDelay * 2, MAX_RETRY_DELAY_MS);
    }

    function connect() {
      if (disposed) return;
      let socket: WebSocket;
      try {
        socket = new WebSocket(
          `wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`,
        );
      } catch {
        scheduleReconnect();
        return;
      }
      activeSocket = socket;
      socketRef.current = socket;
      const isCurrent = () => !disposed && socketRef.current === socket;

      socket.onopen = () => {
        if (!isCurrent()) return;
        retryDelay = INITIAL_RETRY_DELAY_MS;
        setStatus('connected');
        setSendError('');
      };
      socket.onmessage = (event: MessageEvent) => {
        if (!isCurrent() || typeof event.data !== 'string') return;
        const message = parseMessage(event.data);
        if (!message) return;
        setMessages((previous) =>
          previous.some((entry) => entry.id === message.id)
            ? previous
            : [...previous, message],
        );
      };
      socket.onerror = () => {
        if (!isCurrent()) return;
        setStatus('reconnecting');
        socket.close();
      };
      socket.onclose = () => {
        if (!isCurrent()) return;
        socketRef.current = null;
        scheduleReconnect();
      };
    }

    connect();
    return () => {
      disposed = true;
      clearTimeout(retryTimer);
      socketRef.current = null;
      if (activeSocket) {
        activeSocket.onopen = null;
        activeSocket.onmessage = null;
        activeSocket.onerror = null;
        activeSocket.onclose = null;
        activeSocket.close();
      }
    };
  }, [roomId]);

  useEffect(() => {
    endRef.current?.scrollIntoView({ block: 'end' });
  }, [messages]);

  function sendMessage(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const text = draft.trim();
    if (!text) return;
    const socket = socketRef.current;
    if (!socket || socket.readyState !== WebSocket.OPEN) {
      setSendError('Wait for the connection before sending. Your draft is saved.');
      return;
    }
    try {
      // The server assigns the message ID, author, and sentAt, then broadcasts it.
      socket.send(JSON.stringify({ text }));
      setDraft('');
      setSendError('');
    } catch {
      setSendError('Message could not be sent. Please try again.');
    }
  }

  return (
    <section aria-label={`Chat room ${roomId}`}>
      <h2>Room {roomId}</h2>
      {status !== 'connected' && (
        <div role="status">
          {status === 'reconnecting' ? 'Reconnecting…' : 'Connecting…'}
        </div>
      )}
      <div
        role="log"
        aria-label="Messages"
        aria-live="polite"
        aria-relevant="additions"
        style={{ maxHeight: '24rem', overflowY: 'auto' }}
      >
        {messages.map((message) => (
          <article key={message.id}>
            <strong>{message.author}</strong>{' '}
            <span>{String(message.sentAt)}</span>
            <p style={{ whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }}>
              {message.text}
            </p>
          </article>
        ))}
        <div ref={endRef} />
      </div>
      <form onSubmit={sendMessage}>
        <label>
          Message
          <input
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            autoComplete="off"
          />
        </label>
        <button type="submit" disabled={status !== 'connected' || !draft.trim()}>
          Send
        </button>
        {sendError && <p role="alert">{sendError}</p>}
      </form>
    </section>
  );
}

