import { useEffect, useId, useState } from 'react';

type Todo = { id: string; text: string; completed: boolean };
type Filter = 'all' | 'active' | 'done';

const STORAGE_KEY = 'todo-board-items';

function loadTodos(): Todo[] {
  try {
    const value: unknown = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]');
    if (!Array.isArray(value)) return [];
    const ids = new Set<string>();
    return value.filter((item): item is Todo => {
      if (
        typeof item !== 'object' || item === null ||
        typeof item.id !== 'string' || !item.id || ids.has(item.id) ||
        typeof item.text !== 'string' || !item.text.trim() ||
        typeof item.completed !== 'boolean'
      ) return false;
      ids.add(item.id);
      return true;
    });
  } catch {
    return [];
  }
}

export function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(loadTodos);
  const [newText, setNewText] = useState('');
  const [filter, setFilter] = useState<Filter>('all');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editText, setEditText] = useState('');
  const [storageError, setStorageError] = useState(false);
  const inputId = useId();
  const headingId = useId();

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
      setStorageError(false);
    } catch {
      setStorageError(true);
    }
  }, [todos]);

  const visibleTodos = todos.filter(todo =>
    filter === 'all' || (filter === 'done' ? todo.completed : !todo.completed),
  );
  const remaining = todos.filter(todo => !todo.completed).length;

  function moveTodo(id: string, direction: -1 | 1) {
    // Swap with the next visible item, preserving hidden items' positions.
    const visibleIndex = visibleTodos.findIndex(todo => todo.id === id);
    const neighbor = visibleTodos[visibleIndex + direction];
    if (!neighbor) return;
    setTodos(current => {
      const from = current.findIndex(todo => todo.id === id);
      const to = current.findIndex(todo => todo.id === neighbor.id);
      if (from < 0 || to < 0) return current;
      const reordered = [...current];
      [reordered[from], reordered[to]] = [reordered[to], reordered[from]];
      return reordered;
    });
  }

  return (
    <section aria-labelledby={headingId}>
      <h1 id={headingId}>Todo board</h1>
      <form onSubmit={event => {
        event.preventDefault();
        const text = newText.trim();
        if (!text) return;
        setTodos(current => [...current, { id: crypto.randomUUID(), text, completed: false }]);
        setNewText('');
      }}>
        <label htmlFor={inputId}>New todo</label>{' '}
        <input id={inputId} value={newText} onChange={event => setNewText(event.target.value)} />{' '}
        <button type="submit" disabled={!newText.trim()}>Add</button>
      </form>

      <p role="status">{remaining} {remaining === 1 ? 'item' : 'items'} remaining</p>
      {storageError && <p role="alert">Your changes could not be saved to this browser. They will last only for this session.</p>}

      <div role="group" aria-label="Filter todos">
        {(['all', 'active', 'done'] as const).map(option => (
          <button key={option} type="button" aria-pressed={filter === option} onClick={() => {
            setFilter(option);
            setEditingId(null);
          }}>
            {option === 'all' ? 'All' : option === 'active' ? 'Active' : 'Done'}
          </button>
        ))}
      </div>

      {visibleTodos.length === 0 ? (
        <p>{todos.length === 0 ? 'No todos yet. Add one above.' : `No ${filter} todos.`}</p>
      ) : (
        <ul>
          {visibleTodos.map((todo, index) => (
            <li key={todo.id}>
              <label>
                <input type="checkbox" checked={todo.completed} onChange={() => {
                  setTodos(current => current.map(item => item.id === todo.id ? { ...item, completed: !item.completed } : item));
                }} />{' '}
                {todo.completed ? <s>{todo.text}</s> : todo.text}
              </label>{' '}
              {editingId === todo.id ? (
                <form onSubmit={event => {
                  event.preventDefault();
                  const text = editText.trim();
                  if (!text) return;
                  setTodos(current => current.map(item => item.id === todo.id ? { ...item, text } : item));
                  setEditingId(null);
                }}>
                  <input aria-label={`Edit ${todo.text}`} autoFocus value={editText}
                    onChange={event => setEditText(event.target.value)}
                    onKeyDown={event => {
                      if (event.key === 'Escape') {
                        event.preventDefault();
                        setEditingId(null);
                      }
                    }} />{' '}
                  <button type="submit" disabled={!editText.trim()}>Save</button>{' '}
                  <button type="button" onClick={() => setEditingId(null)}>Cancel</button>
                </form>
              ) : (
                <button type="button" aria-label={`Edit ${todo.text}`} onClick={() => {
                  setEditingId(todo.id);
                  setEditText(todo.text);
                }}>Edit</button>
              )}{' '}
              <button type="button" aria-label={`Delete ${todo.text}`} onClick={() => {
                setTodos(current => current.filter(item => item.id !== todo.id));
                if (editingId === todo.id) setEditingId(null);
              }}>Delete</button>{' '}
              <button type="button" aria-label={`Move ${todo.text} up`} disabled={index === 0}
                onClick={() => moveTodo(todo.id, -1)}>Move up</button>{' '}
              <button type="button" aria-label={`Move ${todo.text} down`} disabled={index === visibleTodos.length - 1}
                onClick={() => moveTodo(todo.id, 1)}>Move down</button>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

