import { useEffect, useId, useState } from 'react';
import type { FormEvent } from 'react';

type Todo = { id: string; text: string; done: boolean };
type Filter = 'all' | 'active' | 'done';

const STORAGE_KEY = 'todo-board-items';

function restoreTodos(): Todo[] {
  try {
    const saved: unknown = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]');
    if (!Array.isArray(saved)) return [];
    const ids = new Set<string>();
    return saved.filter((item): item is Todo => {
      if (
        typeof item !== 'object' || item === null ||
        typeof item.id !== 'string' || !item.id || ids.has(item.id) ||
        typeof item.text !== 'string' || !item.text.trim() ||
        typeof item.done !== 'boolean'
      ) return false;
      ids.add(item.id);
      return true;
    });
  } catch {
    return [];
  }
}

export function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(restoreTodos);
  const [newText, setNewText] = useState('');
  const [filter, setFilter] = useState<Filter>('all');
  const [editing, setEditing] = useState<{ id: string; text: string } | null>(null);
  const [storageError, setStorageError] = useState(false);
  const inputId = useId();

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
      setStorageError(false);
    } catch {
      setStorageError(true);
    }
  }, [todos]);

  const visibleTodos = todos.filter(todo =>
    filter === 'all' || (filter === 'done' ? todo.done : !todo.done),
  );
  const remaining = todos.filter(todo => !todo.done).length;

  function addTodo(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const text = newText.trim();
    if (!text) return;
    const todo: Todo = { id: crypto.randomUUID(), text, done: false };
    setTodos(current => [...current, todo]);
    setNewText('');
  }

  function saveEdit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!editing?.text.trim()) return;
    const { id, text } = editing;
    setTodos(current => current.map(todo =>
      todo.id === id ? { ...todo, text: text.trim() } : todo,
    ));
    setEditing(null);
  }

  function moveTodo(id: string, direction: -1 | 1) {
    // Swap adjacent visible items, preserving hidden items' positions.
    setTodos(current => {
      const visible = current.filter(todo =>
        filter === 'all' || (filter === 'done' ? todo.done : !todo.done),
      );
      const index = visible.findIndex(todo => todo.id === id);
      const neighbor = visible[index + direction];
      if (index < 0 || !neighbor) return current;
      const from = current.findIndex(todo => todo.id === id);
      const to = current.findIndex(todo => todo.id === neighbor.id);
      const reordered = [...current];
      [reordered[from], reordered[to]] = [reordered[to], reordered[from]];
      return reordered;
    });
  }

  return (
    <section aria-label="Todo board">
      <h1>Todo board</h1>
      <form onSubmit={addTodo}>
        <label htmlFor={inputId}>New todo</label>{' '}
        <input
          id={inputId}
          value={newText}
          onChange={event => setNewText(event.target.value)}
          placeholder="What needs doing?"
        />{' '}
        <button type="submit" disabled={!newText.trim()}>Add todo</button>
      </form>

      <p role="status">{remaining} {remaining === 1 ? 'item' : 'items'} remaining</p>
      {storageError && <p role="alert">Changes could not be saved to this browser. Your list will stay available until you leave this page.</p>}

      <div role="group" aria-label="Filter todos">
        {(['all', 'active', 'done'] as const).map(value => (
          <button
            key={value}
            type="button"
            aria-pressed={filter === value}
            onClick={() => { setFilter(value); setEditing(null); }}
          >
            {value === 'all' ? 'All' : value === 'active' ? 'Active' : 'Done'}
          </button>
        ))}
      </div>

      {visibleTodos.length === 0 ? (
        <p>{todos.length === 0 ? 'No todos yet. Add one to get started.' : `No ${filter} todos.`}</p>
      ) : (
        <ul>
          {visibleTodos.map((todo, index) => (
            <li key={todo.id}>
              <label>
                <input
                  type="checkbox"
                  checked={todo.done}
                  onChange={() => {
                    setTodos(current => current.map(item =>
                      item.id === todo.id ? { ...item, done: !item.done } : item,
                    ));
                    if (editing?.id === todo.id) setEditing(null);
                  }}
                />{' '}
                {todo.done ? <s>{todo.text}</s> : todo.text}
              </label>{' '}

              {editing?.id === todo.id ? (
                <form onSubmit={saveEdit}>
                  <input
                    aria-label={`Edit ${todo.text}`}
                    autoFocus
                    value={editing.text}
                    onChange={event => setEditing({ id: todo.id, text: event.target.value })}
                    onKeyDown={event => {
                      if (event.key === 'Escape') {
                        event.preventDefault();
                        setEditing(null);
                      }
                    }}
                  />
                  <button type="submit" disabled={!editing.text.trim()}>Save</button>
                  <button type="button" onClick={() => setEditing(null)}>Cancel</button>
                </form>
              ) : (
                <button type="button" aria-label={`Edit ${todo.text}`} onClick={() => setEditing({ id: todo.id, text: todo.text })}>Edit</button>
              )}
              <button
                type="button"
                aria-label={`Delete ${todo.text}`}
                onClick={() => {
                  setTodos(current => current.filter(item => item.id !== todo.id));
                  if (editing?.id === todo.id) setEditing(null);
                }}
              >Delete</button>
              <button type="button" aria-label={`Move ${todo.text} up`} disabled={index === 0} onClick={() => moveTodo(todo.id, -1)}>Move up</button>
              <button type="button" aria-label={`Move ${todo.text} down`} disabled={index === visibleTodos.length - 1} onClick={() => moveTodo(todo.id, 1)}>Move down</button>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

export default TodoBoard;

import Foundation
import SwiftUI

struct SearchResult: Decodable, Identifiable {
    let id: String
    let title: String
    let subtitle: String
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query = ""
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private let session: URLSession
    private var currentSearchID = UUID()

    init(session: URLSession = .shared) {
        self.session = session
    }

    func search(query: String) async {
        guard !Task.isCancelled else { return }

        let searchID = UUID()
        currentSearchID = searchID
        results = []
        errorMessage = nil

        let term = query.trimmingCharacters(in: .whitespacesAndNewlines)
        isLoading = !term.isEmpty
        guard !term.isEmpty else { return }

        defer {
            if currentSearchID == searchID {
                isLoading = false
            }
        }

        do {
            try await Task.sleep(for: .milliseconds(300))

            var components = URLComponents()
            components.scheme = "https"
            components.host = "api.example.com"
            components.path = "/search"
            components.queryItems = [URLQueryItem(name: "q", value: term)]
            guard let url = components.url else {
                throw URLError(.badURL)
            }

            let (data, response) = try await session.data(from: url)
            try Task.checkCancellation()
            guard currentSearchID == searchID else { return }
            guard let response = response as? HTTPURLResponse,
                  (200..<300).contains(response.statusCode) else {
                throw URLError(.badServerResponse)
            }

            results = try JSONDecoder().decode([SearchResult].self, from: data)
        } catch {
            guard !Task.isCancelled, currentSearchID == searchID else { return }
            errorMessage = "Unable to load search results. \(error.localizedDescription)"
        }
    }
}

@MainActor
struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        VStack(spacing: 16) {
            TextField("Search", text: $viewModel.query)
                .textFieldStyle(.roundedBorder)
                .accessibilityLabel("Search")

            if viewModel.isLoading {
                ProgressView("Searching…")
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else if let errorMessage = viewModel.errorMessage {
                Text(errorMessage)
                    .foregroundStyle(.red)
                    .multilineTextAlignment(.center)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else if viewModel.results.isEmpty {
                Text(viewModel.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                     ? "Type to search."
                     : "No results found.")
                    .foregroundStyle(.secondary)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                List(viewModel.results) { result in
                    VStack(alignment: .leading, spacing: 4) {
                        Text(result.title)
                            .font(.headline)
                        Text(result.subtitle)
                            .foregroundStyle(.secondary)
                    }
                }
            }
        }
        .padding()
        .task(id: viewModel.query) {
            await viewModel.search(query: viewModel.query)
        }
    }
}

import { useEffect, useState } from 'react';
import type { User } from './User';

export interface UserProfilesResult {
  profiles: User[];
  loading: boolean;
  error: Error | null;
}

function isUser(value: unknown): value is User {
  if (typeof value !== 'object' || value === null) return false;
  return 'id' in value && typeof value.id === 'string'
    && 'displayName' in value && typeof value.displayName === 'string'
    && 'bio' in value && typeof value.bio === 'string'
    && 'avatarUrl' in value && typeof value.avatarUrl === 'string';
}

/** Loads profiles in input order; any failed request is exposed through error. */
export function useUserProfiles(ids: readonly string[]): UserProfilesResult {
  // Depend on ID values so inline arrays do not cause repeated requests.
  const requestKey = JSON.stringify(ids);
  const [state, setState] = useState<UserProfilesResult & { key: string }>({
    key: requestKey,
    profiles: [],
    loading: ids.length > 0,
    error: null,
  });

  useEffect(() => {
    const requestedIds: string[] = JSON.parse(requestKey);
    const controller = new AbortController();
    let active = true;
    setState({ key: requestKey, profiles: [], loading: requestedIds.length > 0, error: null });

    async function load() {
      try {
        const entries = await Promise.all([...new Set(requestedIds)].map(async (id) => {
          const response = await fetch(`/api/users/${encodeURIComponent(id)}`, {
            signal: controller.signal,
          });
          if (!response.ok) throw new Error(`Unable to load profile ${id} (${response.status}).`);
          const profile: unknown = await response.json();
          if (!isUser(profile)) throw new Error(`Invalid profile data for ${id}.`);
          return [id, profile] as const;
        }));
        const byId = new Map(entries);
        if (active) {
          setState({
            key: requestKey,
            profiles: requestedIds.map((id) => byId.get(id)!),
            loading: false,
            error: null,
          });
        }
      } catch (cause) {
        if (active) {
          controller.abort();
          setState({
            key: requestKey,
            profiles: [],
            loading: false,
            error: cause instanceof Error ? cause : new Error('Unable to load profiles.'),
          });
        }
      }
    }

    if (requestedIds.length > 0) void load();
    return () => {
      active = false;
      controller.abort();
    };
  }, [requestKey]);

  if (state.key !== requestKey) {
    return { profiles: [], loading: ids.length > 0, error: null };
  }
  return { profiles: state.profiles, loading: state.loading, error: state.error };
}

import { useId, useRef, useState, type FormEvent } from 'react';
import type { User } from './User';

export interface ProfileEditorProps {
  user: User;
  onSave: (user: User) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  // A different profile or refreshed server values start a fresh editing session.
  const revision = JSON.stringify([user.id, user.displayName, user.bio, user.avatarUrl]);
  return <ProfileEditorForm key={revision} user={user} onSave={onSave} />;
}

function ProfileEditorForm({ user, onSave }: ProfileEditorProps) {
  const fieldId = useId();
  const [savedUser, setSavedUser] = useState(user);
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const saving = useRef(false);
  const isDirty = displayName !== savedUser.displayName || bio !== savedUser.bio;

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (saving.current || !isDirty) return;

    const updatedUser = { ...savedUser, displayName, bio };
    saving.current = true;
    setIsSaving(true);
    setError(null);
    try {
      await onSave(updatedUser);
      setSavedUser(updatedUser);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : 'Unable to save your profile. Please try again.');
    } finally {
      saving.current = false;
      setIsSaving(false);
    }
  }

  function reset() {
    setDisplayName(savedUser.displayName);
    setBio(savedUser.bio);
    setError(null);
  }

  return (
    <form onSubmit={handleSubmit} aria-label="Edit profile" aria-busy={isSaving}>
      {user.avatarUrl && <img src={user.avatarUrl} alt={`${user.displayName}'s avatar`} width={80} height={80} />}
      <div>
        <label htmlFor={`${fieldId}-name`}>Display name</label>
        <input
          id={`${fieldId}-name`}
          name="displayName"
          value={displayName}
          onChange={(event) => setDisplayName(event.target.value)}
          disabled={isSaving}
        />
      </div>
      <div>
        <label htmlFor={`${fieldId}-bio`}>Bio</label>
        <textarea
          id={`${fieldId}-bio`}
          name="bio"
          value={bio}
          onChange={(event) => setBio(event.target.value)}
          disabled={isSaving}
        />
      </div>
      <p role="status">{isDirty ? 'Unsaved changes' : 'No unsaved changes'}</p>
      {error && <p role="alert">{error}</p>}
      <button type="submit" disabled={isSaving || !isDirty}>
        {isSaving ? 'Saving…' : 'Save'}
      </button>
      <button type="button" onClick={reset} disabled={isSaving}>Reset</button>
    </form>
  );
}

