export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

import { useEffect, useState } from 'react';
import type { User } from './types';

export interface UserProfilesResult {
  profiles: User[];
  isLoading: boolean;
  error: Error | null;
}

function isUser(value: unknown): value is User {
  if (typeof value !== 'object' || value === null) return false;
  return 'id' in value && typeof value.id === 'string'
    && 'displayName' in value && typeof value.displayName === 'string'
    && 'bio' in value && typeof value.bio === 'string'
    && 'avatarUrl' in value && typeof value.avatarUrl === 'string';
}

/** Loads profiles concurrently, preserving the requested order (including duplicates). */
export function useUserProfiles(ids: readonly string[]): UserProfilesResult {
  // Compare ID values so an inline array does not trigger repeated requests.
  const requestKey = JSON.stringify(ids);
  const [state, setState] = useState<UserProfilesResult & { requestKey: string }>({
    requestKey,
    profiles: [],
    isLoading: ids.length > 0,
    error: null,
  });

  useEffect(() => {
    const requestedIds: string[] = JSON.parse(requestKey);
    const controller = new AbortController();
    setState({ requestKey, profiles: [], isLoading: requestedIds.length > 0, error: null });

    if (requestedIds.length === 0) return () => controller.abort();

    async function load() {
      try {
        const profiles = await Promise.all(requestedIds.map(async (id) => {
          const response = await fetch(`/api/users/${encodeURIComponent(id)}`, {
            signal: controller.signal,
          });
          if (!response.ok) throw new Error(`Could not load profile ${id} (${response.status}).`);
          const profile: unknown = await response.json();
          if (!isUser(profile) || profile.id !== id) throw new Error(`Invalid profile response for ${id}.`);
          return profile;
        }));
        if (!controller.signal.aborted) {
          setState({ requestKey, profiles, isLoading: false, error: null });
        }
      } catch (cause) {
        if (controller.signal.aborted) return;
        controller.abort();
        setState({
          requestKey,
          profiles: [],
          isLoading: false,
          error: cause instanceof Error ? cause : new Error('Could not load profiles.'),
        });
      }
    }

    void load();
    return () => controller.abort();
  }, [requestKey]);

  // Do not expose profiles from an earlier request before the effect runs.
  if (state.requestKey !== requestKey) {
    return { profiles: [], isLoading: ids.length > 0, error: null };
  }
  return { profiles: state.profiles, isLoading: state.isLoading, error: state.error };
}

