@MainActor
final class StopwatchViewModel: ObservableObject {
    struct Lap: Identifiable {
        let id: Int
        let split: TimeInterval
    }

    @Published private(set) var elapsed: TimeInterval = 0
    @Published private(set) var isRunning = false
    @Published private(set) var laps: [Lap] = []

    private var timer: AnyCancellable?
    private var startedAt: TimeInterval?
    private var accumulated: TimeInterval = 0
    private var lastLapElapsed: TimeInterval = 0

    func start() {
        guard !isRunning else { return }
        startedAt = ProcessInfo.processInfo.systemUptime
        isRunning = true
        timer = Timer.publish(every: 0.01, on: .main, in: .common)
            .autoconnect()
            .sink { [weak self] _ in
                self?.updateElapsed()
            }
    }

    func stop() {
        guard isRunning else { return }
        updateElapsed()
        accumulated = elapsed
        startedAt = nil
        isRunning = false
        timer?.cancel()
        timer = nil
    }

    func reset() {
        stop()
        accumulated = 0
        elapsed = 0
        lastLapElapsed = 0
        laps.removeAll()
    }

    func lap() {
        guard isRunning else { return }
        updateElapsed()
        laps.append(Lap(id: laps.count + 1, split: elapsed - lastLapElapsed))
        lastLapElapsed = elapsed
    }

    static func formattedTime(_ interval: TimeInterval) -> String {
        let hundredths = Int(max(0, interval) * 100)
        let minutes = hundredths / 6_000
        let seconds = hundredths / 100 % 60
        let fraction = hundredths % 100
        func padded(_ value: Int) -> String {
            value < 10 ? "0\(value)" : String(value)
        }
        return "\(padded(minutes)):\(padded(seconds)).\(padded(fraction))"
    }

    private func updateElapsed() {
        guard let startedAt else { return }
        // Measure time independently of timer delivery to avoid accumulated drift.
        elapsed = accumulated + ProcessInfo.processInfo.systemUptime - startedAt
    }
}

