@MainActor
final class SettingsStore: ObservableObject {
    enum Theme: String, CaseIterable, Identifiable {
        case system, light, dark

        var id: Self { self }

        var title: String { rawValue.capitalized }

        var colorScheme: ColorScheme? {
            switch self {
            case .system: return nil
            case .light: return .light
            case .dark: return .dark
            }
        }
    }

    private enum Key {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    @Published var displayName: String {
        didSet { persist(displayName, forKey: Key.displayName) }
    }

    @Published var theme: Theme {
        didSet { persist(theme.rawValue, forKey: Key.theme) }
    }

    @Published var notificationsEnabled: Bool {
        didSet { persist(notificationsEnabled, forKey: Key.notificationsEnabled) }
    }

    /// The refresh interval in minutes.
    @Published var refreshInterval: Int {
        didSet { persist(refreshInterval, forKey: Key.refreshInterval) }
    }

    private let defaults: UserDefaults
    private var isReloading = false
    private var defaultsObservation: AnyCancellable?

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        defaults.register(defaults: [
            Key.displayName: "",
            Key.theme: Theme.system.rawValue,
            Key.notificationsEnabled: true,
            Key.refreshInterval: 15
        ])
        displayName = defaults.string(forKey: Key.displayName) ?? ""
        theme = Theme(rawValue: defaults.string(forKey: Key.theme) ?? "") ?? .system
        notificationsEnabled = defaults.bool(forKey: Key.notificationsEnabled)
        refreshInterval = defaults.integer(forKey: Key.refreshInterval)

        // Observe all instances, since another instance may write to the same suite.
        defaultsObservation = NotificationCenter.default
            .publisher(for: UserDefaults.didChangeNotification)
            .sink { [weak self] _ in
                Task { @MainActor [weak self] in
                    self?.reload()
                }
            }
    }

    private func persist(_ value: Any, forKey key: String) {
        guard !isReloading else { return }
        defaults.set(value, forKey: key)
    }

    private func reload() {
        isReloading = true
        defer { isReloading = false }

        let newDisplayName = defaults.string(forKey: Key.displayName) ?? ""
        let newTheme = Theme(rawValue: defaults.string(forKey: Key.theme) ?? "") ?? .system
        let newNotificationsEnabled = defaults.bool(forKey: Key.notificationsEnabled)
        let newRefreshInterval = defaults.integer(forKey: Key.refreshInterval)

        if displayName != newDisplayName { displayName = newDisplayName }
        if theme != newTheme { theme = newTheme }
        if notificationsEnabled != newNotificationsEnabled {
            notificationsEnabled = newNotificationsEnabled
        }
        if refreshInterval != newRefreshInterval { refreshInterval = newRefreshInterval }
    }
}

