        var title: String {
            switch self {
            case .system: return "System"
            case .light: return "Light"
            case .dark: return "Dark"
            }
        }
    }

    enum Key {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    @Published var displayName: String {
        didSet {
            if displayName != oldValue { persist(displayName, forKey: Key.displayName) }
        }
    }

    @Published var theme: Theme {
        didSet {
            if theme != oldValue { persist(theme.rawValue, forKey: Key.theme) }
        }
    }

    @Published var notificationsEnabled: Bool {
        didSet {
            if notificationsEnabled != oldValue {
                persist(notificationsEnabled, forKey: Key.notificationsEnabled)
            }
        }
    }

    /// Refresh interval in seconds.
    @Published var refreshInterval: Int {
        didSet {
            if refreshInterval != oldValue { persist(refreshInterval, forKey: Key.refreshInterval) }
        }
    }

    private let defaults: UserDefaults
    private var defaultsObservation: AnyCancellable?
    private var isReloading = false

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        displayName = defaults.string(forKey: Key.displayName) ?? ""
        theme = Theme(rawValue: defaults.string(forKey: Key.theme) ?? "") ?? .system
        notificationsEnabled = defaults.object(forKey: Key.notificationsEnabled) as? Bool ?? true
        refreshInterval = defaults.object(forKey: Key.refreshInterval) as? Int ?? 60

        // Observe all instances so writes through another UserDefaults instance are read too.
        defaultsObservation = NotificationCenter.default
            .publisher(for: UserDefaults.didChangeNotification)
            .sink { [weak self] _ in
                Task { @MainActor [weak self] in
                    self?.reload()
                }
            }
        reload()
    }

    private func persist(_ value: Any, forKey key: String) {
        guard !isReloading else { return }
        defaults.set(value, forKey: key)
    }

    private func reload() {
        isReloading = true
        defer { isReloading = false }

        let storedName = defaults.string(forKey: Key.displayName) ?? ""
        let storedTheme = Theme(rawValue: defaults.string(forKey: Key.theme) ?? "") ?? .system
        let storedNotifications = defaults.object(forKey: Key.notificationsEnabled) as? Bool ?? true
        let storedInterval = defaults.object(forKey: Key.refreshInterval) as? Int ?? 60

        if displayName != storedName { displayName = storedName }
        if theme != storedTheme { theme = storedTheme }
        if notificationsEnabled != storedNotifications { notificationsEnabled = storedNotifications }
        if refreshInterval != storedInterval { refreshInterval = storedInterval }
    }
}

