private final class DownloadedPhoto {
    let image: NSImage
    let downloadedAt: Date

    init(image: NSImage, downloadedAt: Date) {
        self.image = image
        self.downloadedAt = downloadedAt
    }
}

@MainActor
private final class ThumbnailCache {
    static let shared = ThumbnailCache()
    static let relativeDateFormatter = RelativeDateTimeFormatter()

    private let images = NSCache<NSURL, DownloadedPhoto>()
    private var downloads: [URL: Task<DownloadedPhoto, Error>] = [:]

    func photo(for url: URL) async throws -> DownloadedPhoto {
        if let cached = images.object(forKey: url as NSURL) {
            return cached
        }
        if let download = downloads[url] {
            return try await download.value
        }

        // Shared downloads finish even when a cell scrolls off screen.
        let download = Task { @MainActor in
            let (data, response) = try await URLSession.shared.data(from: url)
            if let response = response as? HTTPURLResponse,
               !(200..<300).contains(response.statusCode) {
                throw URLError(.badServerResponse)
            }
            guard let image = NSImage(data: data) else {
                throw URLError(.cannotDecodeContentData)
            }
            let photo = DownloadedPhoto(image: image, downloadedAt: .now)
            images.setObject(photo, forKey: url as NSURL)
            return photo
        }
        downloads[url] = download
        defer { downloads[url] = nil }
        return try await download.value
    }
}

import Foundation

/// A stand-in for the SDK; returns placeholder coordinates without networking.
final class LegacyGeocoder {
    func geocode(
        _ address: String,
        completion: @escaping (Result<(Double, Double), Error>) -> Void
    ) {
        completion(.success((0, 0)))
    }
}

/// A stand-in for the SDK; simulates progress without reading or uploading a file.
final class LegacyUploader {
    var onProgress: ((Double) -> Void)?
    var onFinish: ((Error?) -> Void)?

    func start(file: URL) {
        onProgress?(0)
        onProgress?(0.5)
        onProgress?(1)
        onFinish?(nil)
    }
}

/// Bridges geocoding and a single upload. Create a new bridge for each upload.
actor LegacyBridge {
    enum UploadError: Error {
        case alreadyStarted
    }

    /// Consume from one task while another task awaits `upload(file:)`.
    /// Upload errors are thrown by `upload(file:)`; this stream ends on either outcome.
    nonisolated let progress: AsyncStream<Double>

    private let progressContinuation: AsyncStream<Double>.Continuation
    private let geocoder = LegacyGeocoder()
    private let uploader = LegacyUploader()
    private var uploadStarted = false

    init() {
        let stream = AsyncStream<Double>.makeStream(bufferingPolicy: .bufferingNewest(1))
        progress = stream.stream
        progressContinuation = stream.continuation
    }

    deinit {
        progressContinuation.finish()
    }

    func geocode(_ address: String) async throws -> (Double, Double) {
