/// A single upload. Consume `progress` concurrently with `upload(file:)`.
/// The SDK has no cancellation API, so an in-flight upload runs until it finishes.
@MainActor
final class AsyncUploader {
    enum UploadError: Error {
        case alreadyStarted
    }

    let progress: AsyncStream<Double>

    private let uploader = LegacyUploader()
    private let progressContinuation: AsyncStream<Double>.Continuation
    private var hasStarted = false

    init() {
        let stream = AsyncStream<Double>.makeStream()
        progress = stream.stream
        progressContinuation = stream.continuation
    }

    func upload(file: URL) async throws {
        guard !hasStarted else { throw UploadError.alreadyStarted }
        hasStarted = true

        defer {
            uploader.onProgress = nil
            uploader.onFinish = nil
            progressContinuation.finish()
        }

        try Task.checkCancellation()
        let progressContinuation = progressContinuation
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            uploader.onProgress = { progress in
                progressContinuation.yield(progress)
            }
            // Only the terminal callback resumes the one-shot continuation.
            uploader.onFinish = { error in
                progressContinuation.finish()
                if let error {
                    continuation.resume(throwing: error)
                } else {
                    continuation.resume(returning: ())
                }
            }
            uploader.start(file: file)
        }
        try Task.checkCancellation()
    }

    deinit {
        progressContinuation.finish()
    }
}

import Foundation
import SwiftUI

/// A chat room that connects while visible and reconnects after transport failures.
@MainActor
public struct ChatScreen: View {
    @StateObject private var model = ChatModel()
    @State private var author = "Me"
    @State private var draft = ""
    private let bottomID = "chat-bottom"

    /// Creates a screen for the example chat room.
    public init() {}

    public var body: some View {
        VStack(spacing: 12) {
            Text(model.status)
                .font(.caption)
                .foregroundStyle(.secondary)

            GeometryReader { geometry in
                ScrollViewReader { proxy in
                    ScrollView {
                        LazyVStack(alignment: .leading, spacing: 12) {
                            ForEach(model.messages) { message in
                                VStack(alignment: .leading, spacing: 4) {
                                    Text(message.author).font(.headline)
                                    Text(message.text).textSelection(.enabled)
                                }
                                .frame(maxWidth: .infinity, alignment: .leading)
                            }
                            Color.clear.frame(height: 1).id(bottomID)
                        }
                        .padding()
                    }
                    .onAppear { proxy.scrollTo(bottomID, anchor: .bottom) }
                    .onChange(of: model.messages) { _ in
                        proxy.scrollTo(bottomID, anchor: .bottom)
                    }
                    .onChange(of: geometry.size) { _ in
                        proxy.scrollTo(bottomID, anchor: .bottom)
                    }
                }
            }

            if let error = model.errorMessage {
                Text(error).font(.caption).foregroundStyle(.red)
            }

            HStack {
                TextField("Your name", text: $author).frame(width: 120)
                TextField("Message", text: $draft).onSubmit(send)
                Button("Send", action: send)
                    .disabled(!canSend)
            }
            .textFieldStyle(.roundedBorder)
        }
        .padding()
        .task { await model.run() }
    }

    private var canSend: Bool {
        model.isConnected && !model.isSending
            && !draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && !author.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private func send() {
        guard canSend else { return }
        let text = draft
        let name = author.trimmingCharacters(in: .whitespacesAndNewlines)
        Task {
            if await model.send(text: text, author: name), draft == text {
                draft = ""
            }
        }
    }
}

private struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
private final class ChatModel: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []
    @Published private(set) var isConnected = false
    @Published private(set) var isSending = false
    @Published private(set) var status = "Connecting…"
    @Published private(set) var errorMessage: String?

    private var socket: URLSessionWebSocketTask?
    private var runID: UUID?

    func run() async {
        let id = UUID()
        runID = id
        socket?.cancel(with: .goingAway, reason: nil)
        let session = URLSession(configuration: .default)
        defer {
            session.invalidateAndCancel()
            if runID == id {
                socket = nil
                isConnected = false
                status = "Disconnected"
            }
        }

        guard let url = URL(string: "wss://chat.example.com/room") else { return }
        var retryDelay: UInt64 = 1
        while !Task.isCancelled && runID == id {
            status = "Connecting…"
            isConnected = false
            let connection = session.webSocketTask(with: url)
            socket = connection
            connection.resume()

            do {
                try await withTaskCancellationHandler {
                    // A successful pong confirms that the WebSocket handshake finished.
                    try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                        connection.sendPing { error in
                            if let error {
                                continuation.resume(throwing: error)
                            } else {
                                continuation.resume()
                            }
                        }
                    }
                    try Task.checkCancellation()
                    guard runID == id else { return }
                    isConnected = true
                    status = "Connected"
                    errorMessage = nil

                    while !Task.isCancelled && runID == id {
                        let incoming = try await connection.receive()
                        try Task.checkCancellation()
                        guard runID == id else { return }
                        retryDelay = 1
                        let data: Data
                        switch incoming {
                        case .data(let bytes): data = bytes
                        case .string(let text): data = Data(text.utf8)
                        @unknown default: continue
                        }
                        do {
                            append(try JSONDecoder().decode(ChatMessage.self, from: data))
                        } catch {
                            errorMessage = "An incoming message could not be read."
                        }
                    }
                } onCancel: {
                    connection.cancel(with: .goingAway, reason: nil)
                }
            } catch {
                guard !Task.isCancelled, runID == id else { return }
                errorMessage = "Connection lost: \(error.localizedDescription)"
            }

            connection.cancel(with: .goingAway, reason: nil)
            guard !Task.isCancelled, runID == id else { return }
            socket = nil
            isConnected = false
            status = "Reconnecting in \(retryDelay)s…"
            do {
                try await Task.sleep(nanoseconds: retryDelay * 1_000_000_000)
            } catch {
                return
            }
            retryDelay = min(retryDelay * 2, 30)
        }
    }

    func send(text: String, author: String) async -> Bool {
        guard isConnected, !isSending, let connection = socket else { return false }
        isSending = true
        defer { isSending = false }
        let message = ChatMessage(id: UUID().uuidString, author: author, text: text)
        do {
            let data = try JSONEncoder().encode(message)
            try await connection.send(.string(String(decoding: data, as: UTF8.self)))
            append(message)
            return true
        } catch {
            if socket === connection {
                errorMessage = "Message was not sent. Your draft has been kept."
                isConnected = false
                // Cancelling also wakes the receive loop, which owns reconnection.
                connection.cancel(with: .goingAway, reason: nil)
            }
            return false
        }
    }

    private func append(_ message: ChatMessage) {
        if let index = messages.firstIndex(where: { $0.id == message.id }) {
            messages[index] = message
        } else {
            messages.append(message)
        }
    }
}

import Foundation
import SwiftUI

@MainActor
struct ChatScreen: View {
    @StateObject private var chat = ChatModel()
    @State private var draft = ""

    var body: some View {
        VStack(spacing: 0) {
            Text(chat.status)
                .font(.caption)
                .foregroundStyle(.secondary)
                .padding()

            ScrollViewReader { proxy in
