                        }
                        Color.clear.frame(height: 1).id("bottom")
                    }
                    .padding()
                }
                .onAppear { proxy.scrollTo("bottom", anchor: .bottom) }
                .onChange(of: chat.messages) { _ in
                    proxy.scrollTo("bottom", anchor: .bottom)
                }
            }

            if let error = chat.messageError {
                Text(error)
                    .font(.caption)
                    .foregroundStyle(.red)
                    .padding(.horizontal)
            }

