                    .disabled(!canSend)
            }
            .padding()
        }
        .onAppear { chat.start() }
        .onDisappear { chat.stop() }
    }

    private var canSend: Bool {
        chat.isConnected && !chat.isSending
            && !draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private func send() {
        guard canSend else { return }
        let submittedDraft = draft
        Task {
            if await chat.send(submittedDraft), draft == submittedDraft {
                draft = ""
            }
        }
    }
}

private struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
private final class ChatModel: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []
    @Published private(set) var status = "Disconnected"
    @Published private(set) var isConnected = false
    @Published private(set) var isSending = false
    @Published private(set) var messageError: String?

    private var connectionTask: Task<Void, Never>?
    private var socket: URLSessionWebSocketTask?
    private var generation = UUID()
    private let maximumRetryDelay = 30

    func start() {
        guard connectionTask == nil else { return }
        let generation = UUID()
        self.generation = generation
        connectionTask = Task { [weak self] in
            await self?.receiveMessages(generation: generation)
        }
    }

    func stop() {
        generation = UUID()
        connectionTask?.cancel()
        connectionTask = nil
        socket?.cancel(with: .goingAway, reason: nil)
        socket = nil
        isConnected = false
        isSending = false
        status = "Disconnected"
    }

    func send(_ text: String) async -> Bool {
        guard isConnected, !isSending, let socket else { return false }
        isSending = true
        messageError = nil
        defer {
            if self.socket === socket { isSending = false }
        }

        do {
            // Outgoing messages use the same envelope as incoming messages.
            let message = ChatMessage(id: UUID().uuidString, author: "Me", text: text)
            let data = try JSONEncoder().encode(message)
            try await socket.send(.string(String(decoding: data, as: UTF8.self)))
            guard self.socket === socket else { return false }
            append(message)
            return true
        } catch {
            guard self.socket === socket else { return false }
            messageError = "Message could not be sent. Try again after reconnecting."
            isConnected = false
            // Cancelling also wakes the receive loop, which owns reconnection.
            socket.cancel(with: .goingAway, reason: nil)
            return false
        }
    }

    private func receiveMessages(generation: UUID) async {
        guard let url = URL(string: "wss://chat.example.com/room") else { return }
        var retryDelay = 1

        while !Task.isCancelled, self.generation == generation {
            status = "Connecting…"
            let socket = URLSession.shared.webSocketTask(with: url)
            self.socket = socket
            socket.resume()

            do {
                // A pong confirms the connection, unlike resume() alone.
                try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                    socket.sendPing { error in
                        if let error {
                            continuation.resume(throwing: error)
                        } else {
                            continuation.resume()
                        }
                    }
                }
                try Task.checkCancellation()
                guard self.generation == generation else { return }
                isConnected = true
                status = "Connected"

                while !Task.isCancelled {
                    let frame = try await socket.receive()
                    try Task.checkCancellation()
                    guard self.generation == generation else { return }
                    retryDelay = 1
                    let data: Data
                    switch frame {
                    case .string(let text): data = Data(text.utf8)
                    case .data(let bytes): data = bytes
                    @unknown default: continue
                    }

                    do {
                        append(try JSONDecoder().decode(ChatMessage.self, from: data))
                    } catch {
                        messageError = "An unreadable message was skipped."
                    }
                }
            } catch {
                guard !Task.isCancelled, self.generation == generation else { return }
                status = "Connection lost: \(error.localizedDescription) Retrying in \(retryDelay)s…"
            }

            socket.cancel(with: .goingAway, reason: nil)
            guard !Task.isCancelled, self.generation == generation else { return }
            self.socket = nil
            isConnected = false
            isSending = false
            do {
                try await Task.sleep(for: .seconds(retryDelay))
            } catch {
                return
            }
            retryDelay = min(retryDelay * 2, maximumRetryDelay)
        }
    }

    private func append(_ message: ChatMessage) {
        if let index = messages.firstIndex(where: { $0.id == message.id }) {
            messages[index] = message
        } else {
            messages.append(message)
        }
    }
}
